/* =====================================================================
   PLATFORMS
   How to get a game onto each store, from access to patches. Each guide
   walks the same six stages. `points` are the process, stable for years;
   `facts` are the numbers and rules that change, each with the day it was
   checked and its source (same rules and stale warning as topic facts).
   `nda` says what the platform keeps under NDA, so a thin section is
   explained rather than padded. `glance` feeds the comparison table.
   A UGC platform (kind 'ugc') is engine, hosting and economy in one, so
   its guide walks seven stages of its own and stays out of the table.
   Any stage can carry a `diagram`, drawn above its points.
   ===================================================================== */
const PLATFORM_STAGES = [
  ['access', 'Getting access'], ['build', 'Building for it'], ['cert', 'Review and certification'],
  ['ratings', 'Ratings, privacy and legal'], ['store', 'Store page and money'], ['release', 'Release and after']
];
const UGC_STAGES = [
  ['access', 'Getting started'], ['architecture', 'How a game runs'], ['tools', 'The editor and the language'],
  ['rules', 'Rules, safety and moderation'], ['money', 'Making money'], ['publish', 'Publishing and updates'], ['marketing', 'Marketing and discovery']
];
/** @param {{kind:string}} p */
const stagesOf = p => p.kind === 'ugc' ? UGC_STAGES : PLATFORM_STAGES;
const PLATFORMS = [];
// Channels too small or too closed for a full guide: a note each, with a
// dated fact, or excluded by name with the reason (plan row P6).
/** @type {{t:string, d:string, excluded?:boolean, facts?:any[]}[]} */
const PLATFORM_NOTES = [
  { t:'Apple Arcade', d:'A curated subscription: you put an unreleased game forward to Apple and Apple picks it. Apple publishes no business terms, so the money is set in your agreement with Apple, and a free-to-play economy has to be designed out, not just switched off.',
    facts:[{ claim:'Apple Arcade games play without ads or in-app purchases.', asOf:'2026-09-28', src:'https://developer.apple.com/apple-arcade/' }] },
  { t:'WeChat mini games', d:'A mini game runs inside WeChat on a JavaScript runtime, and every version is reviewed before release. Download size is the constraint that shapes the build; publishing a paid or monetised game in mainland China also needs a government licence (not verified here against an official page).',
    facts:[{ claim:'Each mini game version is reviewed before it can be released, normally within one calendar day.', asOf:'2026-09-28', src:'https://developers.weixin.qq.com/minigame/introduction/guide/bbsh.html' },
      { claim:'The main package is capped at 4 MB and all packages together at 30 MB.', asOf:'2026-09-28', src:'https://developers.weixin.qq.com/minigame/dev/guide/base-ability/subPackage/useSubPackage.html' }] },
  { t:'GOG', d:'A curated PC store: you submit through its form, GOG reviews every submission and gets in touch only if it decides to release the game. Its revenue terms are not on the page below, so none is quoted.',
    facts:[{ claim:'GOG reviews every submission, contacts the developer only if it will release the game, and asks for games that are finished or already released elsewhere.', asOf:'2026-09-28', src:'https://support.gog.com/hc/en-us/articles/11382878039197-Releasing-your-game-on-GOG-FAQ' }] },
  { t:'Xbox Game Pass and Netflix Games', excluded:true, d:'Both are deals negotiated one game at a time, and neither publishes its terms, so there is no public process or dated fact to teach. The Xbox guide names PC Game Pass only in its subtitle.' }
];
/** @param {string} id @param {any} o */
function PLATFORM(id, o){ o.id = id; PLATFORMS.push(o); }
const CHECKED = '2026-09-24';

PLATFORM('steam', { t:'Steam', kind:'pc', sub:'Windows, Mac, Linux and Steam Deck',
  short:'Open to anyone: pay a fee per game, pass a store page review and a build review, then press Release yourself.',
  glance:['Anyone; $100 per game','Store page, then build','3 to 5 business days each'],
  stages:{
    access:{ points:['Sign up to Steamworks as a person or a company. There is no NDA and no concept approval.','Pay the app fee for each game, then give bank, tax and identity details.','Your first game cannot release until 30 days after its fee is paid.'],
      facts:[{ claim:'The Steam Direct fee is $100 per game, paid back to you once the game earns $1,000 in adjusted gross revenue.', asOf:CHECKED, src:'https://partner.steamgames.com/doc/gettingstarted/appfee' },
        { claim:'A new partner waits 30 days after paying the app fee before the first game can release; tax verification can take 2 to 7 business days.', asOf:CHECKED, src:'https://partner.steamgames.com/doc/gettingstarted/onboarding' }] },
    build:{ points:['Build for Windows, Mac or Linux with any engine. There is no dev kit.','The Steamworks SDK (achievements, cloud saves, Steam Input, Workshop) is optional, but anything the store page promises must work.','Steam Deck compatibility review is optional and grades a game Verified, Playable or Unsupported.','Steam Input lets players remap any controller; Deck review checks that on-screen glyphs match the pad in hand, and Valve recommends the ISteamInput API because it shows the right glyphs automatically.','Cloud saves: Auto-Cloud needs only paths in App Admin; add root overrides if saves should follow a player across Windows, Mac and Deck.','Automate uploads: a CI job runs steamcmd with a dedicated build account, or GameCI’s steam-deploy action on GitHub; Unreal projects can drive the same step from BuildGraph (see the Unreal guide).'],
      facts:[{ claim:'Steam Deck Verified checks controller input and on-screen glyphs, default settings that run well, no launcher warnings, and text at least 9 pixels tall at 1280 by 800.', asOf:CHECKED, src:'https://partner.steamgames.com/doc/steamdeck/compat' },
        { claim:'SteamPipe uploads are scripted: steamcmd runs +login <build account> +run_app_build <app_build VDF> +quit, and the app build script names the AppID, ContentRoot, BuildOutput and one depot build script per depot.', asOf:'2026-09-28', src:'https://partner.steamgames.com/doc/sdk/uploading' },
        { claim:'GameCI’s game-ci/steam-deploy@v3 GitHub Action uploads from CI with the secrets STEAM_USERNAME, STEAM_CONFIG_VDF (a base64 config.vdf from a local Steam Guard login) and STEAM_APP_ID, plus rootPath, depot paths and a releaseBranch.', asOf:'2026-09-28', src:'https://game.ci/docs/github/deployment/steam' },
        { claim:'Steam Cloud comes two ways: Auto-Cloud syncs configured folders with no code, and the ISteamRemoteStorage API gives the game control; each game sets a byte quota and a file count per user.', asOf:'2026-09-28', src:'https://partner.steamgames.com/doc/features/cloud' }] },
    cert:{ points:['Two reviews: the store page first, then the build. The page must be approved before the build can be submitted.','The page may show only what is in the game at launch, and screenshots must show gameplay.','The build must start on every system it claims and do what the page advertises. Answer the content survey, including AI-generated content, before review.'],
      facts:[{ claim:'Store page review and build review each typically take 3 to 5 business days; Valve asks for submission at least 7 business days before launch.', asOf:CHECKED, src:'https://partner.steamgames.com/doc/store/review_process' }] },
    ratings:{ points:['Steam does not use IARC. Its content survey produces ratings for several regional boards, with required sections for Germany and Indonesia.','Every partner completes a tax interview; Valve collects and pays VAT and GST in many countries, and store prices include it.'],
      facts:[{ claim:'US tax on US-source income defaults to 30% withholding for non-US partners, reduced where a tax treaty applies.', asOf:CHECKED, src:'https://partner.steamgames.com/doc/finance/taxfaq' }] },
    store:{ points:['Required art: header, small, main and vertical capsules, and at least five gameplay screenshots at 1920 by 1080.','A Coming Soon page collects wishlists, and wishlisters are emailed at launch.','Set a base price and regional prices; discount rules limit how soon after launch or a price change you can discount.'],
      facts:[{ claim:'A new game must be public as Coming Soon for at least two weeks before it can release.', asOf:CHECKED, src:'https://partner.steamgames.com/doc/store/coming_soon' },
        { claim:'Payouts are monthly, once a month’s sales pass $100, about 30 days after the month ends.', asOf:CHECKED, src:'https://partner.steamgames.com/doc/finance/payments_salesreporting' },
        { claim:'Valve’s revenue share was reported in 2018 as 30% up to $10 million per game, 25% to $50 million, and 20% above; the agreement itself is not public.', asOf:CHECKED, src:'https://gameinformer.com/2018/11/30/valve-adjusting-revenue-share-for-steams-most-popular-games' },
        { claim:'Players can refund within 14 days of purchase if they have played under 2 hours.', asOf:CHECKED, src:'https://store.steampowered.com/steam_refunds/' }] },
    release:{ points:['An approved game does not release itself: you press Release.','Patches go live when you set a build live on the default branch; test it on a password-protected branch first.','Demos and playtests are separate app entries with their own review. Early Access games must be playable now and promise nothing specific about the future.'],
      facts:[{ claim:'Steam Next Fest runs three times a year; a game needs a public demo and must be unreleased, and can take part only once.', asOf:CHECKED, src:'https://partner.steamgames.com/doc/marketing/upcoming_events/nextfest' },
        { claim:'SteamPipe splits each file into roughly 1 MB chunks and sends only changed chunks, so Valve advises limiting pack files to about 1 or 2 GB, grouping assets by level, not reordering them, and aligning Unreal paks to 1 MB.', asOf:'2026-09-28', src:'https://partner.steamgames.com/doc/sdk/uploading' },
        { claim:'A build can be set live on a beta branch automatically with SetLive in the app build script, but never on the default branch: that is done by hand on the Builds page, and setting a build live on a released app is confirmed by the account’s phone number or Steam Mobile App.', asOf:'2026-09-28', src:'https://partner.steamgames.com/doc/sdk/uploading' }],
      deploy:[
        { t:'Create a build account', d:'In Steamworks, add a separate Steam account with only the Edit App Metadata and Publish App Changes To Steam permissions, used just for uploads; to set builds live on a released app it also needs a phone number or the Steam Mobile App.' },
        { t:'Set launch options', d:'In App Admin, Installation, General, add one launch option per executable and operating system, then publish.' },
        { t:'Define depots', d:'On the SteamPipe Depots page add depots, set an OS or language only on depots that are OS- or language-specific, publish, and add new depots to your packages.' },
        { t:'Write the VDF scripts', d:'In the SDK ContentBuilder folder, write app_build_<appid>.vdf naming ContentRoot, BuildOutput, a description and each depot_build script with its FileMapping.' },
        { t:'Upload with steamcmd', d:'Run steamcmd +login <build account> +run_app_build <path to app_build VDF> +quit and approve the first Steam Guard prompt.' },
        { t:'Set live on a beta branch', d:'On the Builds page create a password-protected branch, choose it under Set build live for branch, click Preview Change, then Set Build Live Now.', shot:{ img:'assets/platforms/steam-branches.webp', alt:'A Steamworks branch table listing default, alpha14 and alpha13 branches with build ids, usage share and Disable and Update buttons', caption:'Branches in Steamworks: each row is a branch with the build it serves and the share of players on it.', credit:{ author:'Valve', url:'https://partner.steamgames.com/doc/store/application/branches', licence:'press', source:'Steamworks Documentation' }, callouts:[{ x:0.59, y:0.62, t:'No password: any owner can opt in' }] } },
        { t:'Test the beta build', d:'Opt in from the client under Properties, Game Versions and Betas, then play it on every OS and a Steam Deck.' },
        { t:'Promote to default', d:'Back on the Builds page, set the same build live on the default branch by hand, confirm by phone or the Steam Mobile App, and post patch notes.' }
      ],
      shots:[{ img:'assets/platforms/steam-launch-options.webp', alt:'Five Steamworks launch option forms: game.exe on Windows, Game.app on macOS, game.x64 on Linux plus SteamOS, a Windows option gated on owning a DLC, and a macOS binary path, each with executable and operating system fields', caption:'Launch options in App Admin: one per executable and operating system, set before any depot is uploaded.', credit:{ author:'Valve', url:'https://partner.steamgames.com/doc/sdk/uploading', licence:'press', source:'Steamworks Documentation' }, callouts:[{ x:0.56, y:0.18, t:'OS decides where this option is offered' }] }],
      iv:[
        { q:'Walk me through shipping a patch on Steam.', a:'Build it in CI, upload with steamcmd and an app_build script, set it live on a password beta branch, test it on each OS and a Deck, then set the same build live on default by hand and post patch notes as an event.', follow:'How do you roll back if the patch breaks saves?', red:'Uploading straight to default with no beta test, or not knowing default cannot be set live from a script.' },
        { q:'How do you roll back a bad Steam build?', a:'Every upload is kept with its build id, so I open the Builds page and set the previous build live on the default branch again; players download only the changed chunks back.', follow:'What if the bad build already migrated save files?', red:'Saying you must rebuild and re-upload the old version.' },
        { q:'Why is our 200 MB change a 5 GB Steam download?', a:'SteamPipe diffs about 1 MB chunks, so if the pack layout shifts, every chunk after the change looks new. Keep packs 1 to 2 GB, group by level, never reorder assets, and pad Unreal paks to 1 MB.', follow:'How would you measure patch size before release?', red:'Blaming Steam compression without looking at pack layout.' },
        { q:'How would you automate Steam uploads from CI safely?', a:'A dedicated build account with only publish rights, its Steam Guard login cached as config.vdf in a secret, steamcmd or GameCI steam-deploy uploading to a beta branch with SetLive, and a human promoting to default.', follow:'What happens when the cached login expires?', red:'Putting a personal admin account password in CI.' },
        { q:'What do you check before submitting for Steam Deck Verified?', a:'Steam Input glyphs that match the Deck, default settings that run well at 1280 by 800, text at least 9 pixels tall, and any launcher fully navigable with a controller; cloud saves help but are not a Verified criterion.', follow:'What if a middleware launcher cannot be removed?', red:'Assuming Proton working means Verified.' },
        { q:'How do you run a public playtest before launch?', a:'Either a Steam Playtest app entry players request access to, or a demo app for Next Fest; both are separate apps with their own review, while beta branches suit people who already own the game.', follow:'Why not just hand out beta keys?', red:'Using the default branch of the main app as a public test.' }
      ] }
  },
  flow:{ kind:'flow', title:'Steam, from sign-up to release',
    steps:[{id:'account', t:'Steamworks sign-up', d:'person or company'},{id:'fee', t:'Pay the app fee', d:'the 30-day wait starts'},{id:'page', t:'Build the store page', d:'art, text, content survey'},{id:'pagerev', t:'Store page review', d:'3 to 5 business days'},{id:'soon', t:'Coming Soon', d:'at least two weeks of wishlists'},{id:'buildrev', t:'Build review', d:'3 to 5 business days'},{id:'release', t:'Press Release', d:'nothing happens until you do'}],
    edges:[['account','fee'],['fee','page'],['page','pagerev'],['pagerev','soon'],['pagerev','buildrev'],['soon','release'],['buildrev','release']] },
  topics:['platform-access','certification-and-review','store-presence','release-and-updates']
});

PLATFORM('nintendo', { t:'Nintendo Switch', kind:'console', sub:'Switch and Switch 2',
  short:'Register free, sign the NDA, apply for Switch access, then build, rate and pass Nintendo’s review. Almost everything technical is under NDA.',
  glance:['Free portal; NDA and approval','Nintendo review (Lotcheck)','Under NDA'],
  nda:'The SDK, dev kits, technical requirements, review checklist, timings, store specifications and revenue share are all under NDA. The partner portal covers them after you sign.',
  stages:{
    access:{ points:['Register free on the Nintendo Developer Portal, even as an individual, and accept the NDA.','Apply separately for access to Nintendo Switch development information.','Sign a publishing agreement before release.'],
      facts:[{ claim:'The Nintendo Developer Portal accepts individual developers; access to Switch information needs a separate application after registration.', asOf:CHECKED, src:'https://developer.nintendo.com/the-process' },
        { claim:'The portal states that Nintendo is not currently accepting requests for access to the Switch 2 development environment.', asOf:CHECKED, src:'https://developer.nintendo.com/web/development/home/developing-for-switch2' }] },
    build:{ points:['The SDK, dev kit hardware and technical requirements arrive only after approval.','Unity is listed as supported middleware. Unreal gives console source only after you prove approval.','Godot has no official console export: use middleware (such as W4 Games or RAWRLAB) or a porting studio, and still register with Nintendo.'],
      facts:[{ claim:'The Godot project states that console export needs third-party middleware or a porting company, because console SDKs are under NDA.', asOf:CHECKED, src:'https://godotengine.org/consoles/' }] },
    cert:{ points:['Nintendo reviews every product before release (often called Lotcheck) against its guidelines.','Keep the guidelines in mind from the start, and ask the portal team early about anything unusual.'] },
    ratings:{ points:['Digital releases are rated through IARC. Japan needs a CERO rating directly, and boxed releases need ratings from each board.'],
      facts:[{ claim:'IARC lists Nintendo among its storefronts.', asOf:CHECKED, src:'https://globalratings.com/storefronts/' },
        { claim:'CERO (Japan) is not among IARC’s rating authorities.', asOf:CHECKED, src:'https://globalratings.com/participants/' }] },
    store:{ shots:[{ img:'assets/platforms/nintendo-store-page.webp', alt:'The Nintendo Store web page for Hades on Nintendo Switch: key art with a gallery strip of screenshots and a trailer below it, the version and edition, a price of $24.99, a Direct download button, and an ESRB Teen rating with its content descriptors', caption:'A game’s public Nintendo eShop page on the web: the price you set, the gallery and trailer, and the rating from IARC.', credit:{ author:'Nintendo', url:'https://www.nintendo.com/us/store/products/hades-switch/', licence:'capture', source:'Nintendo Store (public page)' }, callouts:[{ x:0.72, y:0.52, t:'The price you set' }, { x:0.59, y:0.77, t:'Screenshots and trailer' }, { x:0.1, y:0.83, t:'Rating and descriptors from IARC' }] }], points:['You set the price and release date on the Nintendo eShop.','Store assets, payouts and the revenue share are in the agreements, not public.'] },
    release:{ points:['Patches, DLC and price promotions are submitted through the portal after launch.','Nintendo’s public process page lists updates among post-launch support but does not say how they are reviewed; until the portal documentation says otherwise, budget review time into every hotfix plan.','The submission tools, patch size rules and review times are under NDA; nothing public describes them screen by screen, so this guide gives no click-by-click walkthrough and no portal screenshot.','Any build or submission tooling is documented only under NDA; engine side, Unity and Unreal console build targets appear only after approval (see the Unity and Unreal guides).'],
      deploy:[
        { t:'Register on the portal', d:'Create a free Nintendo Developer Portal account as a person or company and accept the portal NDA.' },
        { t:'Apply for Switch access', d:'From the portal, submit the separate application for Nintendo Switch development information and wait for approval.' },
        { t:'Get tools and kits', d:'After approval, get the SDK and documentation through the portal; development hardware is arranged under the NDA.' },
        { t:'Sign the publishing agreement', d:'Before any release, sign the agreement that covers eShop distribution, payouts and the revenue share.' },
        { t:'Rate the game', d:'Complete IARC for digital regions and apply to CERO directly if the game ships in Japan.' },
        { t:'Submit for review', d:'Submit the game for Nintendo’s review, which checks that it can be played safely and meets Nintendo’s production standards (developers often call it Lotcheck); the checklist itself is under NDA.' },
        { t:'Set the eShop release', d:'After passing review, set your price and release date for the eShop, then submit later patches the same way.' }
      ],
      iv:[
        { q:'Walk me through shipping a patch on Switch, in public terms.', a:'Fix and version the build, run our own test pass against Nintendo’s guidelines, submit it the way the portal documentation describes, allow time for any review Nintendo applies, then release once it is cleared. How updates are reviewed, the checklist, timings and tooling are all under NDA, so I would plan with the portal team.', follow:'How would you plan a day-one patch around review time?', red:'Promising a same-day hotfix without checking Nintendo’s update process.' },
        { q:'How would you get a small team onto Switch?', a:'Register free on the Nintendo Developer Portal, accept the NDA, apply separately for Switch access, then choose an engine with a supported console path: Unity or Unreal after proving approval, or middleware or a porting studio for Godot.', follow:'What changes for Switch 2 today?', red:'Assuming a Switch export button exists in an engine without approval.' },
        { q:'What can you say publicly about Lotcheck?', a:'That Nintendo reviews a game before release to check that it can be played safely and meets its production standards. How updates are reviewed, the guideline list, fail categories and turnaround are under NDA, so I would not quote them outside the company.', follow:'How do you keep a team NDA-safe when writing public postmortems?', red:'Quoting internal checklist items in public.' },
        { q:'Why can a Switch port miss its date even when the game is done?', a:'Review and ratings sit on the critical path: IARC for digital, CERO for Japan, and a possible resubmission if review fails. A fail means another round, so the schedule needs slack.', follow:'Which of these can start before the build is final?', red:'Treating console review as a formality.' },
        { q:'How do you avoid a huge Switch download for a small fix?', a:'Keep data packed so changes touch few files and do not reorder assets between builds. Any Nintendo rules on patch size are under NDA, so I would check them on the portal before launch.', follow:'How would you measure patch size before submitting?', red:'Rebuilding every asset archive for each patch.' }
      ] }
  },
  flow:{ kind:'flow', title:'Nintendo Switch, from sign-up to release',
    steps:[{id:'reg', t:'Register and sign the NDA', d:'free, individuals accepted'},{id:'apply', t:'Apply for Switch access', d:'a separate application'},{id:'dev', t:'Develop with the SDK', d:'kits and rules under NDA'},{id:'agree', t:'Publishing agreement', d:'before release'},{id:'rate', t:'Age ratings', d:'IARC, plus CERO for Japan'},{id:'review', t:'Nintendo review', d:'Lotcheck'},{id:'eshop', t:'eShop release', d:'your price and date'}],
    edges:[['reg','apply'],['apply','dev'],['dev','agree'],['agree','rate'],['rate','review'],['review','eshop']] },
  topics:['platform-access','platform-requirements','certification-and-review','ratings-and-disclosures']
});

PLATFORM('playstation', { t:'PlayStation', kind:'console', sub:'PS5',
  short:'Apply through PlayStation Partners as a registered company, sign the agreements, then build to Sony’s requirements and pass its testing.',
  glance:['Registered company; NDA','Sony testing (TRC)','Under NDA'],
  nda:'The SDK, DevNet, dev kits, the Technical Requirements Checklist (TRC), testing timings, store specifications and revenue share are under NDA.',
  stages:{
    access:{ points:['Apply through PlayStation Partners. The form asks where your company or institution is registered.','Accepted partners sign agreements under NDA before they see the SDK.'],
      facts:[{ claim:'PlayStation Partners registration asks where the applicant’s company or institution is registered.', asOf:CHECKED, src:'https://register.playstation.net/' },
        { claim:'In 2022 Sony offered newly registered partners with an accepted concept one dev kit and one test kit on loan; check with your partner contact that this still applies.', asOf:CHECKED, src:'https://sonyinteractive.com/en/news/blog/complimentary-development-hardware/' }] },
    build:{ points:['The SDK, DevNet documentation and PS5 kits come after approval, under NDA.','Unity and Unreal console support need proof of approval from Sony; Godot goes through middleware or a porting studio.','Trophies, saves, activities and accessibility rules are in the TRC.'],
      facts:[{ claim:'Unreal Engine’s PS5 support is available after you confirm approved PlayStation 5 developer status with Epic.', asOf:CHECKED, src:'https://dev.epicgames.com/documentation/en-us/unreal-engine/development-for-playstation-5-in-unreal-engine' }] },
    cert:{ points:['Sony tests every submission against the TRC before release.','Plan for resubmission: a failed item means another round of testing.'] },
    ratings:{ points:['Digital releases are rated through IARC; Japan needs CERO directly, and boxed releases need ratings from each board.'],
      facts:[{ claim:'IARC lists PlayStation among its storefronts.', asOf:CHECKED, src:'https://globalratings.com/storefronts/' }] },
    store:{ shots:[{ img:'assets/platforms/playstation-store-page.webp', alt:'The PlayStation Store web page for Hades: key art, PS4 and PS5 platform tags, a 4.83 star rating from 19K ratings, a sale price of $7.49 against $24.99 with the lowest price in the last 30 days, Add to Cart, and an ESRB Teen rating with descriptors', caption:'A game’s public PlayStation Store page: platform tags, player ratings, a discount shown against the 30-day lowest price, and the IARC rating.', credit:{ author:'Sony Interactive Entertainment', url:'https://store.playstation.com/en-us/product/UP2125-PPSA03355_00-3466019145463410', licence:'capture', source:'PlayStation Store (public page)' }, callouts:[{ x:0.2, y:0.5, t:'Platform tags: PS4, PS5' }, { x:0.29, y:0.625, t:'Discount against the 30-day lowest price' }, { x:0.49, y:0.7, t:'IARC rating and descriptors' }] }], points:['Self-publishing on PlayStation Store means you own the IP and pick the date.','The revenue share and store specifications are in the agreements, not public.'] },
    release:{ points:['Patch and day-one patch rules are under NDA; plan them with your partner contact.','Every patch is a new submission tested against the TRC, so a hotfix carries testing time.','The submission portal, patch size limits and upload tools are under NDA and have no public screens, so this guide ships no portal screenshot and only a public-level walkthrough.','Plan accessibility features (subtitles, remapping, text size) early; PlayStation’s own requirements are not public, so the public Xbox Accessibility Guidelines (see the Xbox guide) are arguably the best open reference.'],
      facts:[{ claim:'Sony states that once registration is approved and the Global Developer and Publisher Agreement (GDPA) is signed, partners get development tools, publishing resources, documentation and Help Center support.', asOf:'2026-09-28', src:'https://sonyinteractive.com/en/news/blog/showing-your-game-to-playstation/' }],
      deploy:[
        { t:'Apply to PlayStation Partners', d:'Fill in the PlayStation Partners registration form with where your company or institution is registered.' },
        { t:'Sign the agreements', d:'Once your registration is approved, sign the Global Developer and Publisher Agreement (GDPA), which Sony says unlocks its development tools, publishing resources, documentation and Help Center support.' },
        { t:'Get dev and test kits', d:'Ask your partner contact about PS5 development and test kits; in 2022 Sony offered newly registered partners with an accepted concept one of each free, to be returned within two years, so confirm the current terms.' },
        { t:'Build to the TRC', d:'Build with the tools and documentation you receive and test against Sony’s technical requirements before submitting; what they demand of trophies, saves and system features is under NDA.' },
        { t:'Rate the game', d:'Complete IARC for digital storefronts, apply to CERO for Japan, and board ratings for boxed releases.' },
        { t:'Submit for testing', d:'Submit the build as the partner documentation describes; the process, requirements and timings are under NDA, so plan time to fix failures and resubmit.' },
        { t:'Release on the store', d:'After passing, set the release date and price for PlayStation Store with your partner contact.' }
      ],
      iv:[
        { q:'Walk me through shipping a patch on PlayStation, in public terms.', a:'Branch the fix, run a full TRC self-check on test kits, submit through the partner tools, wait for Sony’s testing, fix and resubmit if anything fails, then release once it passes. Tool names and timings are under NDA.', follow:'How do you decide what goes in a day-one patch?', red:'Assuming a patch can skip testing because it is small.' },
        { q:'What is the TRC and why does it matter to a designer?', a:'The Technical Requirements Checklist Sony tests against. It covers things like trophies, saves and system features, so designing save flow or account handling without reading it causes late rework. Its contents are under NDA.', follow:'Give an example of a design choice a requirement could force.', red:'Thinking only programmers need to read it.' },
        { q:'How does a small studio get PS5 kits?', a:'Register on PlayStation Partners as a company, get accepted and sign the agreements; Sony announced in 2022 that newly registered partners with an accepted concept could borrow one dev kit and one test kit, which I would confirm with the partner contact.', follow:'Why might you use a porting studio instead?', red:'Believing you can develop on a retail console.' },
        { q:'Your submission failed one TRC item a week before launch. What do you do?', a:'Read the failure report, fix the item on a branch with only that change, retest the related TRC areas, resubmit, and tell marketing the date is at risk until it passes.', follow:'How would you prevent this next time?', red:'Hoping for a waiver without talking to the partner contact.' },
        { q:'How do you keep patch sizes small on PS5?', a:'Group data so a fix touches few files, avoid reordering packed assets, and measure the patch against the previous build before submitting; the exact limits and tools are under NDA.', follow:'What engine settings affect pack layout?', red:'Blaming the store for size without checking pack layout.' }
      ] }
  },
  flow:{ kind:'flow', title:'PlayStation, from application to release',
    steps:[{id:'apply', t:'Apply to PlayStation Partners', d:'as a registered company'},{id:'nda', t:'Agreements and NDA', d:'before the SDK'},{id:'kits', t:'SDK and dev kits', d:'DevNet access'},{id:'dev', t:'Build to the TRC', d:'trophies, saves, accessibility'},{id:'test', t:'Submission and testing', d:'against the TRC'},{id:'store', t:'PlayStation Store release', d:'you pick the date'}],
    edges:[['apply','nda'],['nda','kits'],['kits','dev'],['dev','test'],['test','store']] },
  topics:['platform-access','platform-requirements','certification-and-review']
});

PLATFORM('xbox', { t:'Xbox and Microsoft Store', kind:'console', sub:'Xbox Series X|S, PC Game Pass, Microsoft Store',
  short:'Console games using Xbox services go through ID@Xbox. Xbox publishes its requirements and certification times; PC games can use the Microsoft Store directly.',
  glance:['ID@Xbox (NDA); PC store free','Every build certified','4 business days, 2 for updates'],
  nda:'The console SDK details and Xbox-specific graphics APIs are under NDA. The Xbox Requirements and certification times are public.',
  stages:{
    access:{ points:['For console games with Xbox services, apply to ID@Xbox: be 18 or older, sign an NDA, and be in a country Microsoft works with.','The older Xbox Creators Program published UWP games with a limited set of Xbox services (sign-in and leaderboards, no achievements or online multiplayer); UWP is no longer developed, so confirm with Microsoft before planning on it.','PC games can go on the Microsoft Store directly.'],
      facts:[{ claim:'ID@Xbox requires members to be 18 or older, to sign an NDA and to be in a country where Microsoft can do business.', asOf:CHECKED, src:'https://developer.microsoft.com/en-us/games/publish/' },
        { claim:'The Microsoft Store developer registration no longer charges a fee under the new onboarding.', asOf:CHECKED, src:'https://learn.microsoft.com/en-us/windows/apps/publish/get-started' }] },
    build:{ points:['The public GDK covers PC Game Pass and cloud; console tools need onboarding as a partner with a Microsoft Entra ID tenant.','Read the Xbox Requirements (XRs) before designing saves, achievements and suspend and resume: they are public.'],
      facts:[{ claim:'Xbox Requirements version 16.4 is dated 8 September 2026.', asOf:CHECKED, src:'https://learn.microsoft.com/en-us/gaming/gdk/docs/store/policies/console/certification-requirements' },
        { claim:'Console games must ship with 10 to 100 achievements worth 1,000 gamerscore at launch, and must treat Series X and Series S equally.', asOf:CHECKED, src:'https://learn.microsoft.com/en-us/gaming/gdk/docs/store/policies/console/certification-requirements' },
        { claim:'Secure GDK downloads need an organisation onboarded as an Xbox partner; personal Microsoft accounts are no longer supported.', asOf:CHECKED, src:'https://learn.microsoft.com/en-us/gaming/gdk/docs/gdk-dev/development-downloads/access-resources' }] },
    cert:{ points:['Every submission goes through certification, updates included: submission checks, build verification tests, then XR testing.','Blocking failures come back as Conditions for Resubmission; exceptions to an XR are agreed with your Microsoft contacts before you submit.'],
      facts:[{ claim:'Certification targets 4 business days for a base digital game, 2 for a content update and 5 for a disc submission.', asOf:CHECKED, src:'https://learn.microsoft.com/en-us/gaming/game-publishing/concepts/certification/certification-guide' }] },
    ratings:{ points:['Every product needs an IARC questionnaire, even with board certificates; boxed releases need long-form ratings from each board.','Paid random items must show their odds before purchase.'],
      facts:[{ claim:'Microsoft Store policy 10.8.4 requires the odds of each item in a paid random reward to be shown before purchase.', asOf:CHECKED, src:'https://learn.microsoft.com/en-us/windows/apps/publish/store-policies' }] },
    store:{ points:['You can reserve a store name up to three months before publishing.','Game Pass deals are made through your Microsoft contacts.','The console store’s revenue share is not public.'],
      facts:[{ claim:'The Microsoft Store (PC) fee for games sold through Microsoft’s commerce is 12%.', asOf:CHECKED, src:'https://learn.microsoft.com/en-us/windows/apps/publish/get-started' }] },
    release:{ points:['After a pass, the game is released from certification and your Microsoft contact coordinates release.','Game Preview is Xbox’s early access and shows a notice at launch; saves must survive updates.','Console title updates go through certification again (2 business days as a target); console packages (XVC, built with makepkg) need enrolment as an Xbox creator, so the walkthrough below uses the ordinary MSIX app flow in Partner Center that any Microsoft Store developer can follow.','PC games built with the GDK ship as MSIXVC packages made with makepkg; a game packaged as an ordinary MSIX app follows the steps below, its updates can roll out gradually to a percentage of Windows customers, and after the first submission in Partner Center the Microsoft Store submission API can automate later ones from CI.','The Xbox Accessibility Guidelines (XAGs) are public best practice, not a certification checklist, and help plan subtitles, remapping and text size early.'],
      facts:[{ claim:'Microsoft’s publishing guide says PC games built with the GDK use the MSIXVC package format and console games use XVC, both made with MakePkg.', asOf:'2026-09-28', src:'https://learn.microsoft.com/en-us/gaming/game-publishing/tutorial-xbox-managed/how-to-create-a-package' },
        { claim:'XR-055 caps a single achievement at 200 gamerscore and requires every achievement to be achievable; XR-057 requires base-game achievements to be earnable without buying in-title content and forbids changing an achievement’s unlock rules once it is published.', asOf:'2026-09-28', src:'https://learn.microsoft.com/en-us/gaming/gdk/docs/store/policies/console/certification-requirements' },
        { claim:'The Xbox Accessibility Guidelines are version 3.2, published 8 June 2023, and Microsoft describes them as best practices rather than a compliance checklist.', asOf:'2026-09-28', src:'https://learn.microsoft.com/en-us/gaming/accessibility/guidelines' },
        { claim:'Partner Center’s Packages page accepts .msix, .msixupload, .msixbundle, .appx, .appxupload and .appxbundle files, and recommends .msixupload or .appxupload for Windows 10 and later.', asOf:'2026-09-28', src:'https://learn.microsoft.com/en-us/windows/apps/publish/publish-your-app/msix/upload-app-packages' },
        { claim:'An update to a published MSIX app can roll out gradually to a percentage of Windows 10 or 11 customers, and the percentage can be raised or the update halted without a new submission.', asOf:'2026-09-28', src:'https://learn.microsoft.com/en-us/windows/apps/publish/publish-your-app/msix/upload-app-packages' },
        { claim:'An MSIX submission has Pricing and availability, Properties, Age ratings, Packages, Store listings and Submission options pages, then Submit for certification; the Microsoft Store submission API can automate it.', asOf:'2026-09-28', src:'https://learn.microsoft.com/en-us/windows/apps/publish/publish-your-app/msix/create-app-submission' }],
      deploy:[
        { t:'Reserve the name', d:'In Partner Center, create the app by reserving its name, which opens the application overview page.' },
        { t:'Start a submission', d:'In the Product release section of the overview, click Start submission to create a draft submission.' },
        { t:'Set pricing and availability', d:'Choose markets, audience, discoverability, release schedule and base price on the Pricing and availability page.' },
        { t:'Fill properties and ratings', d:'Set the category on Properties, plus a privacy policy URL if the game collects personal information, then answer every Age ratings question for IARC.' },
        { t:'Upload the MSIX package', d:'On Packages, drag in the .msixupload file, remove, fix and re-upload any package that fails validation, and choose device families.', shot:{ img:'assets/platforms/xbox-msix-packages.webp', alt:'The Partner Center Packages page for a sample app: a drop zone for .msix and .appx files, a warning that at least one package is required, and Device family availability checkboxes', caption:'The Packages page in Partner Center: drop the MSIX upload file, then pick which Windows device families may get it.', credit:{ author:'Microsoft', url:'https://learn.microsoft.com/en-us/windows/apps/publish/publish-your-app/msix/upload-app-packages', licence:'press', source:'Microsoft Learn' }, callouts:[{ x:0.86, y:0.33, t:'Drop the .msixupload here' },{ x:0.62, y:0.66, t:'Device families that may acquire it' }] } },
        { t:'Write the store listing', d:'For at least one language, add a description and at least one screenshot (four or more recommended), plus store logos and Xbox images where required.' },
        { t:'Submit for certification', d:'Optionally add notes for certification under Submission options, then click Submit for certification on the application overview page.' },
        { t:'Roll out updates gradually', d:'For each later update, tick the gradual rollout box on Packages and raise the percentage as crash data stays clean.' }
      ],
      iv:[
        { q:'Walk me through shipping a patch on Xbox.', a:'Build the title update, test it against the public Xbox Requirements, submit it for certification through the partner tools, fix any Conditions for Resubmission, then release it with the Microsoft contact once it passes; updates target 2 business days.', follow:'What if the patch needs an exception to an XR?', red:'Not knowing updates are certified too.' },
        { q:'How do you ship and patch a PC game on the Microsoft Store?', a:'If it is packaged as an ordinary MSIX app, upload the .msixupload to a new submission in Partner Center, pass certification, and for updates use gradual rollout so a percentage of players get it first; after that first submission in Partner Center, the submission API can drive later ones from CI. A GDK game uploads an MSIXVC package built with makepkg instead.', follow:'How do you stop a bad rollout?', red:'Uploading an EXE installer and expecting Store rollout controls.' },
        { q:'Which public Xbox rules shape design before any code?', a:'The Xbox Requirements cover saves, achievements, suspend and resume and treating Series X and S equally, and the Xbox Accessibility Guidelines are best-practice guidance on subtitles, remapping and text size.', follow:'Are the XAGs a certification gate?', red:'Calling the XAGs a compliance checklist.' },
        { q:'How would you plan achievements for an Xbox launch?', a:'Launch with 10 to 100 achievements worth 1,000 gamerscore, none worth more than 200, every one achievable without buying add-ons and earned through play rather than purchases or cheats; more can be added later within the semi-annual and lifetime limits.', follow:'Why plan unlock rules carefully before release?', red:'Treating achievements as optional on console.' },
        { q:'Your update failed certification. What next?', a:'Read the Conditions for Resubmission, fix only the blocking items, rerun the related tests, resubmit, and talk to the Microsoft contact early if an exception is needed.', follow:'How do you keep a hotfix narrow?', red:'Adding new features to the resubmission.' }
      ] }
  },
  flow:{ kind:'flow', title:'Xbox, from ID@Xbox to release',
    steps:[{id:'idx', t:'Join ID@Xbox', d:'18+, NDA, supported country'},{id:'gdk', t:'GDK and Partner Center', d:'an Entra ID tenant'},{id:'xr', t:'Build to the XRs', d:'public requirements'},{id:'sub', t:'Submit for certification', d:'4 business days'},{id:'rel', t:'Release', d:'with your Microsoft contact'}],
    edges:[['idx','gdk'],['gdk','xr'],['xr','sub'],['sub','rel']] },
  topics:['platform-access','platform-requirements','certification-and-review','ratings-and-disclosures']
});

PLATFORM('google-play', { t:'Google Play', kind:'mobile', sub:'Android phones and tablets',
  short:'Pay a one-time fee, verify your identity, run a closed test if you are a new personal account, then fill in the store forms and pass review.',
  glance:['Anyone; $25 once','Review of every release','Up to 7 days'],
  stages:{
    access:{ points:['Register a Play Console account as a person or an organisation, with a one-time fee and identity checks.','New personal accounts must run a closed test before they can publish to production.'],
      facts:[{ claim:'Play Console registration costs $25 once.', asOf:CHECKED, src:'https://support.google.com/googleplay/android-developer/answer/6112435' },
        { claim:'Personal accounts created after 13 November 2023 need a closed test with at least 12 testers opted in for 14 days in a row before applying for production.', asOf:CHECKED, src:'https://support.google.com/googleplay/android-developer/answer/14151465' },
        { claim:'Android developer verification is enforced on certified devices from 30 September 2026 in Brazil, Indonesia, Singapore and Thailand, and worldwide from 2027.', asOf:CHECKED, src:'https://developer.android.com/developer-verification' }] },
    build:{ points:['Upload an Android App Bundle that targets the API level Google currently requires.','Native code, which Unity, Unreal and Godot builds contain, must support 16 KB memory pages in apps targeting Android 15 or later.','Crash and freeze rates above Google’s thresholds can lower your visibility.','Sign with an upload key you keep; Play App Signing holds the app signing key that signs what users install, so a lost upload key can be reset but the signing key is never in your build.','Automate uploads with a Google Play service account: Gradle Play Publisher for Gradle builds, or fastlane supply for any engine’s exported AAB (see the Unity, Unreal and Godot guides for the export itself).'],
      facts:[{ claim:'From 31 August 2026 new apps and updates must target Android 16 (API 36); an extension to 1 November 2026 can be requested.', asOf:CHECKED, src:'https://support.google.com/googleplay/android-developer/answer/11926878' },
        { claim:'Android vitals flags a game when user-perceived crashes pass 1.09% or freezes (ANRs) pass 0.47%, averaged over 28 days.', asOf:CHECKED, src:'https://developer.android.com/games/optimize/vitals' },
        { claim:'New apps are enrolled in Play App Signing automatically: you sign the bundle with an upload key (RSA 2048-bit or more) and Google signs the APKs it delivers with the app signing key it manages.', asOf:'2026-09-28', src:'https://support.google.com/googleplay/android-developer/answer/9842756' },
        { claim:'Gradle Play Publisher uploads with ./gradlew publishBundle and moves a release with ./gradlew promoteArtifact; track defaults to internal, userFraction to 0.1, and releaseStatus to COMPLETED, with credentials from a service account JSON key. Its maintainers now accept pull requests but ignore issues.', asOf:'2026-09-28', src:'https://github.com/Triple-T/gradle-play-publisher' },
        { claim:'fastlane supply (upload_to_play_store) takes --aab, --track, --rollout and --json_key, and its track_promote_to option promotes a release to another track.', asOf:'2026-09-28', src:'https://docs.fastlane.tools/actions/upload_to_play_store/' }] },
    cert:{ points:['Every release is reviewed. Plan for a week.','Managed publishing lets you decide when an approved release goes live.'],
      facts:[{ claim:'Google says review can take up to seven days, or longer in exceptional cases, for some developer accounts.', asOf:CHECKED, src:'https://support.google.com/googleplay/android-developer/answer/9859751' }] },
    ratings:{ points:['Complete the IARC questionnaire for every app.','Fill in the Data safety form, including data your SDKs collect, and link a privacy policy, even if you collect nothing.','Paid random items must show their odds before purchase.'],
      facts:[{ claim:'The Data safety form is required for every app on closed, open or production tracks, including apps that collect no data.', asOf:CHECKED, src:'https://support.google.com/googleplay/android-developer/answer/10787469' }],
      shots:[{ img:'assets/platforms/google-play-data-safety.webp', alt:'A Google Play store listing on a phone showing the Data safety section: no data shared with third parties, no data collected, data encrypted in transit, data deletion on request, Families Policy and independent security review, above ratings and reviews', caption:'What your Data safety form becomes: the section players see on your store listing.', credit:{ author:'Google', url:'https://support.google.com/googleplay/android-developer/answer/10787469', licence:'press', source:'Play Console Help' }, callouts:[{ x:0.92, y:0.41, t:'Includes what your SDKs collect' }] }] },
    store:{ points:['The listing needs an icon, a feature graphic and screenshots; pre-registration can run before launch.','In-app digital goods use Google Play Billing unless a policy exception applies.'],
      facts:[{ claim:'Google announced a new service-fee model on 4 March 2026, taking effect by region between 30 June 2026 and 30 September 2027; until then the rest of the world pays 15% on the first $1 million a year and 30% above.', asOf:CHECKED, src:'https://support.google.com/googleplay/android-developer/answer/112622' },
        { claim:'Pre-registration campaigns can run for up to 90 days.', asOf:CHECKED, src:'https://support.google.com/googleplay/android-developer/answer/9084187' }] },
    release:{ points:['Staged rollouts release an update to a share of users first, so you can stop a bad build.','Vitals thresholds keep applying after launch.','Test tracks come in three sizes: internal for the team in minutes, closed for chosen lists, open for anyone who joins from the store.','Rollout percentages never rise on their own: you raise, halt or resume them from Manage rollout.','Crash reporting and analytics SDKs (such as Firebase Crashlytics) add logs, custom keys and non-fatal errors that vitals does not collect; whatever they collect goes on the Data safety form.'],
      facts:[{ claim:'Internal testing allows up to 100 testers; closed testing lists hold up to 2,000 users each, with up to 50 lists per track; open testing is unlimited unless you set a cap of at least 1,000.', asOf:'2026-09-28', src:'https://support.google.com/googleplay/android-developer/answer/9845334' },
        { claim:'Staged rollouts apply only to updates, not a first release; percentages do not increase automatically, a halt stops new users getting the update, and countries cannot be removed once a rollout starts.', asOf:'2026-09-28', src:'https://support.google.com/googleplay/android-developer/answer/6346149' }],
      deploy:[
        { t:'Export a signed app bundle', d:'Build a release AAB from your engine at the required target API and sign it with your upload key.' },
        { t:'Set up Play App Signing', d:'On the first release, follow the Play App Signing prompt to let Google generate and hold the app signing key.' },
        { t:'Create an internal release', d:'In Play Console, open Test and release, Testing, Internal testing, click Create new release and upload the AAB.' },
        { t:'Name it and add notes', d:'Enter a release name and localised release notes, click Save as draft, then Next.' },
        { t:'Preview, confirm and roll out', d:'On Preview and confirm, fix every error (warnings do not block), then click Start rollout.' },
        { t:'Promote through the tracks', d:'Move the same bundle to Closed testing and then Open testing, with tester lists or Google Groups for the closed track.' },
        { t:'Start a staged production rollout', d:'On Production, Releases, click Edit, enter a percentage in the Staged rollout section and click Start rollout to production.' },
        { t:'Raise or halt the rollout', d:'Watch vitals and reviews, then use Manage rollout, Update rollout to raise the percentage, or Halt rollout to stop.' }
      ],
      iv:[
        { q:'Walk me through shipping a patch on Google Play.', a:'CI builds a signed AAB at the target API, fastlane supply or Gradle Play Publisher pushes it to internal testing, we promote to closed or open testing, then start production at a small staged percentage and raise it while crash and ANR rates hold.', follow:'Which vitals numbers would make you halt?', red:'Going straight to 100% production, or not knowing staged rollout exists.' },
        { q:'A staged rollout at 10% shows a crash spike. What do you do?', a:'Halt it from Manage rollout so no new users get it; the 10% keep the build, so I ship a fixed build with a higher version code as a new release, because Play cannot roll users back to an older version code.', follow:'How do you protect users already on the bad build?', red:'Saying you can simply reinstate the previous build for everyone.' },
        { q:'We lost the keystore. Can we still ship updates?', a:'With Play App Signing, yes: that was the upload key, so we generate a new one and request an upload key reset in Play Console, and Google keeps signing with the app signing key it holds.', follow:'What if the app predates Play App Signing and self-signs?', red:'Proposing a new package name as the first option.' },
        { q:'What goes on the Data safety form for a game with ads and analytics?', a:'Everything the app and its SDKs collect or share, such as device IDs, crash logs and purchase history, whether it is encrypted in transit and whether users can ask for deletion; it is needed even with no data collected.', follow:'How do you find out what an ad SDK collects?', red:'Declaring only data your own code collects.' },
        { q:'How do you automate Play uploads from CI safely?', a:'A service account with release rights only on this app, its JSON key in a CI secret, uploads to internal or closed tracks automatically, and a person starting the production rollout.', follow:'How would you rotate that key?', red:'Committing the service account JSON or the keystore to the repository.' }
      ] }
  },
  flow:{ kind:'flow', title:'Google Play, from account to rollout',
    steps:[{id:'acct', t:'Play Console account', d:'$25, identity checks'},{id:'test', t:'Closed test', d:'12 testers, 14 days (new personal accounts)'},{id:'build', t:'App Bundle at target API', d:'16 KB pages for native code'},{id:'forms', t:'Data safety and IARC', d:'privacy policy linked'},{id:'review', t:'Review', d:'plan a week'},{id:'roll', t:'Staged rollout', d:'a share of users first'}],
    edges:[['acct','test'],['test','build'],['test','forms'],['build','review'],['forms','review'],['review','roll']] },
  topics:['platform-access','platform-requirements','ratings-and-disclosures','release-and-updates']
});

PLATFORM('apple', { t:'Apple App Store', kind:'mobile', sub:'iPhone, iPad and Mac',
  short:'Join the Apple Developer Program, build with current Xcode, test on TestFlight, fill in App Store Connect and pass App Review for every version.',
  glance:['$99 a year; company needs D-U-N-S','App Review of every version','90% within 24 hours'],
  stages:{
    access:{ points:['Join the Apple Developer Program as an individual or an organisation. An organisation needs a legal entity and a D-U-N-S number.'],
      facts:[{ claim:'The Apple Developer Program costs $99 per membership year, with fee waivers for eligible nonprofits, schools and government bodies.', asOf:CHECKED, src:'https://developer.apple.com/programs/whats-included/' },
        { claim:'Organisations enrol with a legal entity, a D-U-N-S number, legal binding authority and a public website.', asOf:CHECKED, src:'https://developer.apple.com/programs/enroll/' }] },
    build:{ points:['Build with the Xcode and SDK versions Apple currently requires.','Games with Game Center features need the entitlement and Game Center set up in App Store Connect.','Privacy manifests and signed third-party SDKs feed your privacy labels. Beta testers use TestFlight.','Signing needs three things from Certificates, Identifiers and Profiles in your developer account: a distribution certificate, an App ID (bundle identifier) and an App Store provisioning profile tying them together.','Automate signing and uploads with fastlane: match keeps certificates and profiles in one shared store for the team and CI, gym builds, pilot uploads to TestFlight and deliver uploads metadata and builds for review. Unity and Unreal export an Xcode project first (see their guides).'],
      facts:[{ claim:'Since 28 April 2026 apps must be built with Xcode 26 and the iOS 26 SDK or later.', asOf:CHECKED, src:'https://developer.apple.com/news/upcoming-requirements/' },
        { claim:'TestFlight supports up to 100 internal and 10,000 external testers; external builds need beta review.', asOf:CHECKED, src:'https://developer.apple.com/testflight/' },
        { claim:'A TestFlight build can be tested for up to 90 days; the first build added to an external group must pass TestFlight App Review, and later builds may not need a full review.', asOf:'2026-09-28', src:'https://developer.apple.com/help/app-store-connect/test-a-beta-version/testflight-overview' },
        { claim:'fastlane match (sync_code_signing) syncs certificates and profiles across a team, pilot (upload_to_testflight) uploads builds to TestFlight, and deliver (upload_to_app_store) uploads metadata and the binary to App Store Connect.', asOf:'2026-09-28', src:'https://docs.fastlane.tools/actions/' }] },
    cert:{ points:['Every version, update included, goes through App Review.','Placeholder content and crashes are rejected, and demos or betas belong on TestFlight, not the store.','Expedited review exists for critical fixes and event-tied releases.'],
      facts:[{ claim:'Apple states that on average 90% of submissions are reviewed in less than 24 hours.', asOf:CHECKED, src:'https://developer.apple.com/distribute/app-review/' }] },
    ratings:{ points:['Apple uses its own age-rating questionnaire, not IARC.','Privacy nutrition labels are required and must include data your SDKs collect.','Paid random items must show their odds before purchase.','To track players across other companies’ apps or read the advertising identifier, ask through App Tracking Transparency; you may explain first, but may not gate features or reward consent.'],
      facts:[{ claim:'Since iOS 14.5, apps need App Tracking Transparency permission to track users across other companies’ apps and websites or to read the IDFA, which returns zeros without it; privacy labels list data types, use for tracking and linkage to identity.', asOf:'2026-09-28', src:'https://developer.apple.com/app-store/user-privacy-and-data-use/' },
        { claim:'Apple’s age ratings are 4+, 9+, 13+, 16+ and 18+; developers had to answer the new rating questions by 31 January 2026.', asOf:CHECKED, src:'https://developer.apple.com/news/?id=ks775ehf' },
        { claim:'Guideline 3.1.1 requires apps with loot boxes to disclose the odds of each item type before purchase.', asOf:CHECKED, src:'https://developer.apple.com/app-store/review/guidelines/' }] },
    store:{ points:['Pre-orders can open from 2 to 180 days before release.','Payment needs the Paid Apps Agreement, bank and tax details.','In the EU, the Digital Markets Act lets you distribute through alternative marketplaces or your own website, and offer other payment processors or link out; each has its own commission, and a chosen payment option must stay for 12 months.','Store optimisation (ASO) runs on the name, subtitle, keywords, screenshots and preview videos; product page tests compare variants.'],
      facts:[{ claim:'Members of Apple’s Small Business Program (no more than $1 million in proceeds in the prior calendar year, or new to the App Store; enrolment required) pay 15% on paid apps and in-app purchases, instead of the standard 30%.', asOf:CHECKED, src:'https://developer.apple.com/app-store/small-business-program/' },
        { claim:'Since 1 May 2025, apps on the US storefront may link to outside purchase methods.', asOf:CHECKED, src:'https://developer.apple.com/news/?id=9txfddzf' },
        { claim:'In the EU, from 1 October 2026, App Store sales through Apple In-App Purchase pay 26% (15% for small-business and similar programmes), alternative in-app payment processing 20% (10%), and linked out-of-app offers a 15% store services commission (10%) on sales within 7 days of the tap.', asOf:'2026-09-28', src:'https://developer.apple.com/support/dma-and-apps-in-the-eu/' },
        { claim:'In the EU, apps distributed through alternative marketplaces or Web Distribution pay a 5% Core Technology Commission from 1 October 2026, replacing the per-install Core Technology Fee; the initial acquisition fee is removed.', asOf:'2026-09-28', src:'https://developer.apple.com/support/dma-and-apps-in-the-eu/' }] },
    release:{ points:['Release manually or automatically after approval.','Phased release rolls an update out over seven days and can be paused.','Phased release only paces automatic updates: anyone can still download the new version by hand, so it limits exposure but is no rollback.'],
      facts:[{ claim:'Phased release goes 1%, 2%, 5%, 10%, 20%, 50% and 100% of users who have automatic updates on, over seven days, and can be paused for up to 30 days in total.', asOf:CHECKED, src:'https://developer.apple.com/help/app-store-connect/update-your-app/release-a-version-update-in-phases' }],
      deploy:[
        { t:'Register the App ID', d:'In Certificates, Identifiers and Profiles, add an explicit App ID with your bundle identifier and capabilities such as Game Center.' },
        { t:'Create signing assets', d:'Create an Apple Distribution certificate and an App Store provisioning profile for that App ID, or let fastlane match or Xcode automatic signing do it.' },
        { t:'Create the app record', d:'In App Store Connect, Apps, click the add button, choose New App, then fill in the platform, name, language, bundle ID and SKU.' },
        { t:'Archive and upload the build', d:'In Xcode choose Product, Archive, then Distribute App to App Store Connect, or upload the exported IPA with Transporter.' },
        { t:'Test internally on TestFlight', d:'When processing finishes, add the build to an internal group so up to 100 team members install it through TestFlight.' },
        { t:'Open external testing', d:'Create an external group, add the build and test information, submit it for review, and wait for TestFlight App Review to approve it before testers get it.', shot:{ img:'assets/platforms/apple-testflight-group.webp', alt:'An App Store Connect dialog titled Create a New Group with a group name field reading Tropical Forest Explorers and Cancel and Create buttons', caption:'Creating an external TestFlight group: you can add anyone, and its builds may need Beta App Review.', credit:{ author:'Apple', url:'https://developer.apple.com/help/app-store-connect/test-a-beta-version/invite-external-testers', licence:'press', source:'App Store Connect Help' } } },
        { t:'Submit the version for review', d:'On the version page, select the build, finish the metadata, privacy labels and age rating, click Add for Review, then Submit for Review.' },
        { t:'Choose a phased release', d:'Under Phased Release for App Store Automatic Updates, select the seven-day phased option, then release manually or automatically after approval.' }
      ],
      shots:[{ img:'assets/platforms/apple-phased-release.webp', alt:'The App Store Connect version page for iOS App Version 2.0 with release options, a phased release section offering release to all users immediately or over a 7-day period, and a summary rating reset option', caption:'Release options on a version page: when it goes live after review, and whether automatic updates are phased.', credit:{ author:'Apple', url:'https://developer.apple.com/help/app-store-connect/update-your-app/release-a-version-update-in-phases', licence:'press', source:'App Store Connect Help' }, callouts:[{ x:0.38, y:0.69, t:'Phased: 1% to 100% over 7 days' }] }],
      iv:[
        { q:'Walk me through shipping a patch on the App Store.', a:'Bump the build number, let CI archive and sign with match, upload with pilot to TestFlight for internal testers, submit the version with deliver or in App Store Connect, and release it phased over seven days while watching crashes.', follow:'What do you do if review rejects an urgent fix?', red:'Not knowing every update goes through App Review.' },
        { q:'Phased release is at day 3 and crashes are rising. What now?', a:'Pause the phased release to stop automatic updates, then ship a fixed build and ask for expedited review; users who downloaded manually keep the bad version, because phased release is not a rollback.', follow:'How long can you pause?', red:'Believing pausing removes the version from the store.' },
        { q:'Why did the CI build fail with a provisioning profile error?', a:'The profile must match the App ID, include the distribution certificate the machine holds, and cover the entitlements; with match, CI pulls the same certificate and profile readonly instead of creating new ones.', follow:'What happens when the distribution certificate expires?', red:'Fixing it by letting each developer create their own distribution certificate.' },
        { q:'How do you get a game to 5,000 outside testers before launch?', a:'An external TestFlight group or a public link, with test information filled in; the first build passes Beta App Review, and each build lasts 90 days.', follow:'How is that different from an internal group?', red:'Proposing ad hoc builds with device UDIDs for thousands of players.' },
        { q:'Our ad SDK wants the IDFA. What must we do on iOS?', a:'Show the App Tracking Transparency prompt with a clear purpose string, keep the game fully working if the player says no, declare tracking in the privacy labels, and ship the SDK’s privacy manifest.', follow:'What can you measure without ATT consent?', red:'Gating content or rewards on accepting tracking.' },
        { q:'Should we use alternative payments in the EU?', a:'Compare the net: from 1 October 2026 Apple takes 26% through In-App Purchase, 20% with another processor plus that processor’s fee, and 15% on linked web offers, and the choice holds for 12 months.', follow:'What does leaving the App Store for a marketplace cost?', red:'Assuming the DMA means no Apple commission at all.' }
      ] }
  },
  flow:{ kind:'flow', title:'Apple App Store, from enrolment to release',
    steps:[{id:'enrol', t:'Developer Program', d:'$99 a year'},{id:'build', t:'Build with current Xcode', d:'Game Center, privacy manifest'},{id:'tf', t:'TestFlight beta', d:'up to 10,000 testers'},{id:'asc', t:'App Store Connect', d:'listing, privacy, age rating'},{id:'review', t:'App Review', d:'most within 24 hours'},{id:'rel', t:'Release', d:'phased, if you like'}],
    edges:[['enrol','build'],['build','tf'],['build','asc'],['tf','review'],['asc','review'],['review','rel']] },
  topics:['platform-access','platform-requirements','ratings-and-disclosures','release-and-updates']
});

PLATFORM('epic', { t:'Epic Games Store', kind:'open', sub:'PC',
  short:'Self-service publishing with a recoupable fee; you keep all revenue up to a threshold each year.',
  glance:['Anyone; $100 per game','Store review','Not published'],
  stages:{
    access:{ points:['Publish through the Epic Developer Portal; each game pays a submission fee that is paid back later.','The portal is organised as organisation, then product, then sandboxes and deployments; only Owner and Admin roles can create a product, and Epic suggests codenames while in development.'],
      facts:[{ claim:'Epic charges a recoupable $100 submission fee per game.', asOf:CHECKED, src:'https://store.epicgames.com/en-US/distribution' },
        { claim:'Only members with the Owner or Admin role can create a product in the Developer Portal; products, sandboxes and deployments are managed on the Product Settings page.', asOf:'2026-09-28', src:'https://dev.epicgames.com/docs/dev-portal/product-management' }] },
    build:{ points:['Multiplayer games must support crossplay across PC stores; games with achievements on other PC stores must offer them on Epic too.','Each offer has an artifact, and each artifact holds binaries: the uploaded builds. The BuildPatch Tool (BPT) uploads a build folder to the Dev sandbox, chunked so later uploads patch only what changed.','BPT authenticates with its own client ID and secret from Product Settings, not the EOS SDK credentials; pass the secret through an environment variable on CI.','Automate uploads by calling BPT with -mode=UploadBinary after your engine build; in Unreal, a BuildGraph script (see the Unreal guide) can run it as a step after packaging.'],
      facts:[{ claim:'The BuildPatch Tool (1.8.8, the recommended version) uploads binaries to a product’s Dev sandbox with -mode=UploadBinary, taking the organisation, product and artifact IDs, the BPT client ID and secret, a BuildRoot, a BuildVersion unique per artifact whatever the platform, an AppLaunch executable path and an optional CloudDir cache; other modes list, copy, diff, delete and delta-optimise binaries.', asOf:'2026-09-28', src:'https://dev.epicgames.com/docs/epic-games-store/publishing-tools/uploading-binaries/bpt-instructions-180' },
        { claim:'BPT uses separate BuildPatch Tool credentials from the BPT credentials tab of Product Settings; clients listed under SDK Credentials cannot be used with it, and the secret is passed as ClientSecret or, as Epic recommends, ClientSecretEnvVar.', asOf:'2026-09-28', src:'https://dev.epicgames.com/docs/epic-games-store/publishing-tools/uploading-binaries/bpt-instructions-180' }] },
    cert:{ points:['Epic reviews the product and its store page before release.','Builds move between three sandboxes: Dev for uploads and testing, Stage for review and pre-release, Live for players. Promoting an artifact does not carry its deployment ID with it.','Once an artifact is live, a later build marked Bugfix that fixes broken functionality can be published straight from Dev to Live without review; new features, platform changes and anything touching the age rating go back through review.'],
      facts:[{ claim:'An artifact update marked Bugfix can be published without review, straight from the Dev to the Live sandbox, only to fix broken functionality; adding, removing or changing a platform needs a new review.', asOf:'2026-09-28', src:'https://dev.epicgames.com/docs/epic-games-store/publishing-tools/publishing-process/patch-live-builds' },
        { claim:'Promoting an artifact from Dev to Stage or Live does not promote its deployment ID, which must be set again in the destination sandbox.', asOf:'2026-09-28', src:'https://dev.epicgames.com/docs/epic-games-store/store-presence/manage-artifacts' }] },
    ratings:{ points:['IARC ratings are available in the Developer Portal.'] },
    store:{ points:['Developers keep 100% of the first $1 million of net revenue per product each year, then 88%.','Epic Web Shops, launched in October 2025, let a developer sell in-game items through an Epic-hosted shop, shown on PC as a tab of the game’s store page, even for a game not distributed on the store; games can link out to it where a platform allows, and the same revenue share applies to payments Epic processes.'],
      facts:[{ claim:'Since June 2025 developers keep 100% of the first $1 million of net revenue per product each year (the allowance resets on 1 January), then 88%, on purchases made with Epic’s payments.', asOf:CHECKED, src:'https://store.epicgames.com/en-US/news/epic-games-store-updates-revenue-share-keep-100-of-the-first-1m-per-product-per-year' },
        { claim:'Epic announced in May 2025 Epic-hosted webshops for out-of-app purchases, with a 0% store fee on the first $1,000,000 per app per year and 88/12 after that on payments Epic processes, and 5% Epic Rewards for players.', asOf:'2026-09-28', src:'https://store.epicgames.com/en-US/news/new-epic-games-store-webshops-and-revenue-share-update' },
        { claim:'Each product can have one web shop; enabling it needs a product with early store discovery, a working webhook and the Epic Games Store Web Shop Agreement, which only an owner or signatory role can sign.', asOf:'2026-09-28', src:'https://dev.epicgames.com/docs/epic-games-store/store-presence/web-shops/manage-web-shops' }] },
    release:{ points:['Updates are published through the Developer Portal.','Upload each patch with a new BuildVersion, attach it to the artifact, choose the update type, then publish: Bugfix skips review, other types are submitted again.','Patch notes are required for a major update and optional for minor ones and bugfixes.'],
      facts:[{ claim:'Artifact update types include Bugfix for small updates that do not affect the age rating; patch notes are required for major updates only.', asOf:'2026-09-28', src:'https://dev.epicgames.com/docs/epic-games-store/store-presence/manage-artifacts' }],
      deploy:[
        { t:'Create the product', d:'In the Developer Portal, as an Owner or Admin, create the product under your organisation and pay the submission fee.' },
        { t:'Collect the BPT credentials', d:'Open Product Settings, the BPT credentials tab, and save the Build Patch Tool client ID and secret.' },
        { t:'Find the artifact ID', d:'Under Epic Games Store, Artifacts and Binaries, open the offer’s artifact and copy its name and ID from Edit Details; the Download build patch tool button on the same page gets BPT.' },
        { t:'Upload the build', d:'Run BuildPatchTool with -mode=UploadBinary, your BuildRoot, CloudDir, a new BuildVersion and the AppLaunch executable; it lands in the Dev sandbox.' },
        { t:'Attach and test in Dev', d:'Set the uploaded binary as active, add its platforms and update type, then install it through the Epic Games Launcher; organisation members reach Dev by default, and outside testers need a player group.' },
        { t:'Submit for review', d:'Finish the store page, ratings and release date, push everything to Stage from Release Management, and submit it for review there; after approval you push it to Live, at once or on a schedule.' },
        { t:'Ship a later bugfix', d:'Upload a new BuildVersion, then in Release Management choose Make live update, set the new binary active with update type Bugfix, check the preview and publish it straight to Live, ticking the option to update Stage too.' }
      ],
      shots:[{ img:'assets/platforms/epic-product-settings.webp', alt:'The Epic Developer Portal Product Settings page, with a left navigation listing Epic Games Store, Epic Online Services, Analytics and other tools above Product Settings, and a red box around the tabs SDK Download and Credentials, BPT credentials, Sandboxes, Identity Providers, Clients and Player Groups', caption:'Product Settings in the Developer Portal: the BPT credentials tab holds the upload client, and the Sandboxes and Player Groups tabs set who can reach Dev and Stage.', credit:{ author:'Epic Games', url:'https://dev.epicgames.com/docs/dev-portal/product-management', licence:'press', source:'Epic Developer Resources' }, callouts:[{ x:0.403, y:0.355, t:'BPT credentials for uploads' }] }],
      iv:[
        { q:'Walk me through shipping a patch on the Epic Games Store.', a:'CI builds, then runs BPT UploadBinary with a new BuildVersion into the Dev sandbox; we set it active on the artifact, test it in Dev through the launcher, set the update type, and publish: Bugfix goes straight to Live, anything else is reviewed again.', follow:'What makes a patch not qualify as Bugfix?', red:'Assuming every Epic update needs a full re-review, or none does.' },
        { q:'The CI upload fails to authenticate. What do you check?', a:'That it uses the Build Patch Tool credentials from Product Settings rather than EOS SDK credentials, and that the secret is passed through ClientSecretEnvVar from the CI secret store.', follow:'Why keep the secret out of the command line?', red:'Pasting the client secret into the build script in the repository.' },
        { q:'BPT rejects the upload because of the version. Why?', a:'BuildVersion must be unique per artifact across platforms, so reusing 1.0 for Mac after Windows fails; derive it from the build number plus platform.', follow:'How do you move the same binary to another artifact?', red:'Deleting the old binary to reuse its version string.' },
        { q:'We sell for 12 months and earn $1.5 million on Epic. What does Epic take?', a:'Nothing on the first $1 million of net revenue that calendar year, then 12% on the remaining $500,000, so about $60,000, on payments Epic processes.', follow:'When does the allowance reset?', red:'Applying 12% to the whole $1.5 million.' },
        { q:'Why add a Stage step when Bugfix can go straight to Live?', a:'Stage lets you check the store page, release date and binary as players will see them before promotion; a direct Bugfix is for urgent fixes that do not change features, platforms or the rating.', follow:'What happens to the deployment ID when you promote?', red:'Treating Dev as a place real players can reach.' }
      ] }
  },
  topics:['store-presence']
});

PLATFORM('web', { t:'Web and browser portals', kind:'open', sub:'HTML5 and WebGL',
  short:'Your own site has no gatekeeper; portals such as CrazyGames and Poki bring players in exchange for their rules and a revenue split.',
  glance:['Anyone','Portal QA, or none','Varies'],
  stages:{
    access:{ points:['Self-hosting needs no approval: you handle payments, privacy law and hosting yourself. The Web stack engine guide covers the export, hosting and portal SDKs; this guide covers getting onto the portals.','CrazyGames takes submissions from anyone; Poki works by application: you request access to Poki for Developers and it reaches out.','Game jams are a cheap route in: an itch.io jam is free to host or enter, and a jam entry is a finished browser build you can later send to a portal.'],
      facts:[{ claim:'Access to Poki for Developers is by request: developers share details about themselves and Poki reaches out to grant access.', asOf:'2026-09-28', src:'https://developers.poki.com/share' },
        { claim:'itch.io lets anyone create a game jam instantly with a free account.', asOf:'2026-09-28', src:'https://raw.githubusercontent.com/itchio/itch.io/master/docs/creators/game-jams.md' }] },
    build:{ points:['Export HTML5 or WebGL and keep the download small: portals set size and file limits.','For CrazyGames’ mobile homepage, aim for 20 MB before first gameplay.'],
      facts:[{ claim:'CrazyGames limits a game to a 50 MB initial download, 250 MB in total and 1,500 files; the mobile homepage needs an initial download of 20 MB or less.', asOf:'2026-09-28', src:'https://docs.crazygames.com/requirements/technical/' }] },
    cert:{ points:['Portals run their own QA; a full launch on CrazyGames needs its SDK and must land the player straight in gameplay.','CrazyGames runs in two stages: a Basic Launch of 7 to 21 days to a limited audience, with the SDK optional and no monetisation, then a Full Launch only if playtime, conversion to gameplay and retention meet its benchmarks.','Poki hand-picks every game and limits daily releases; its Poki Inspector lets you check a build against Poki’s requirements before its QA and final review.'],
      facts:[{ claim:'CrazyGames’ Basic Launch needs no SDK and has no monetisation, and ends after at least 7 days and 500 plays, or after 21 days; progression to Full Launch depends on average playtime, conversion to gameplay and retention, benchmarked against other games. A game with some metrics at benchmark may be offered another Basic Launch period; one with most below must be resubmitted as a new game with significant improvements.', asOf:'2026-09-28', src:'https://docs.crazygames.com/' }] },
    ratings:{ points:['Portals set their own content rules; CrazyGames asks every game, from Basic Launch on, to comply with PEGI 12.','If the game collects personal data beyond the portal SDK’s events, CrazyGames asks for terms or a privacy notice to new players.'] },
    store:{ points:['Portals pay a share of ad and purchase revenue; terms vary by portal and are agreed on joining.','CrazyGames pays mainly through an ad revenue share, and only ads served through its SDK are allowed.','Poki pays 100% for players who arrive directly and splits 50/50 for players Poki brings, in exchange for web exclusivity; stores and consoles stay yours.'],
      facts:[{ claim:'Poki gives developers 100% of revenue from players who reach the game directly and splits 50/50 for players who come through Poki.com or Poki marketing, and asks for exclusivity on the open web only.', asOf:'2026-09-28', src:'https://sdk.poki.com/' },
        { claim:'CrazyGames’ main monetisation is an advertising revenue share, and only ads served through its SDK are allowed.', asOf:'2026-09-28', src:'https://docs.crazygames.com/requirements/intro/' }],
      shots:[{ img:'assets/platforms/web-crazygames-payment-method.webp', alt:'The CrazyGames developer portal Manage Payment Details page with the Payment Method dropdown open, offering Local Bank Transfer, Wire Transfer, PayPal and Hold payments', caption:'CrazyGames’ payment details form: the portal asks for a payment method before it takes a submission, and Hold payments defers it.', credit:{ author:'CrazyGames', url:'https://docs.crazygames.com/payouts/', licence:'press', source:'CrazyGames Developer Documentation' }, callouts:[{ x:0.7, y:0.93, t:'Hold payments defers payout details' }] }] },
    release:{ points:['Updates are uploaded to the portal or your own host.','On CrazyGames, a game invited to Full Launch is updated with the SDK and submitted again as a new version.'],
      deploy:[
        { t:'Preview on CrazyGames', d:'Open Submit a game in the developer portal and use the Preview tool to test the build as players will see it.' },
        { t:'Submit for Basic Launch', d:'Upload the HTML5 build within the size and file limits, fill in the details and submit it to QA.' },
        { t:'Watch the dashboard metrics', d:'Once live, follow playtime, conversion to gameplay and retention on the Developer Dashboard against the benchmarks.' },
        { t:'Integrate the SDK for Full Launch', d:'If invited, add the CrazyGames SDK, the gameplay start event and SDK ads, then submit the new version.' },
        { t:'Or apply to Poki', d:'Request access to Poki for Developers, upload the build, and fix what the Poki Inspector flags before release.' }
      ],
      iv:[
        { q:'Walk me through shipping a patch to a web portal.', a:'Build the HTML5 export, check the initial download and file count against the portal limits, upload the new version in the portal and pass its QA; on your own host, deploy with cache-busted file names so players do not load a stale build.', follow:'How does the patch change on CrazyGames after a Full Launch invite?', red:'Uploading straight over the live build without checking the size limits.' },
        { q:'Should we launch on Poki or CrazyGames?', a:'Poki is by application and wants open-web exclusivity for a 50/50 split on its traffic; CrazyGames takes anyone, starts with a Basic Launch and only monetises after Full Launch. Pick by whether you want curation or reach across portals.', follow:'Does Poki exclusivity stop a Steam release?', red:'Putting the same game on several portals after agreeing to Poki exclusivity.' },
        { q:'Our Unity WebGL build is 80 MB. What now?', a:'CrazyGames caps the initial download at 50 MB and wants 20 MB for its mobile homepage, so compress, strip unused assets and stream the rest after gameplay starts, measured from the SDK’s gameplay start event.', follow:'How is initial download measured without the SDK?', red:'Assuming the portal will accept it because total size is under 250 MB.' },
        { q:'Our game did not reach Full Launch. What are the options?', a:'Basic Launch ends after 7 to 21 days, so the game does not stay there; if some metrics met the benchmarks CrazyGames may offer another Basic Launch period after improvements, and if most fell short the only route is to improve playtime, conversion and retention significantly and resubmit it as a new game.', follow:'Which metric would you work on first?', red:'Resubmitting the same build hoping for a different result.' },
        { q:'Why enter a game jam before pitching a portal?', a:'A jam forces a small, finished browser build in days and gets real players and feedback, which is the evidence a portal’s QA and metrics look for.', follow:'What do you change between the jam build and the portal build?', red:'Treating the jam entry as the final release without SDK or size work.' }
      ] }
  },
  topics:['platform-choice']
});

PLATFORM('quest', { t:'Meta Quest', kind:'open', sub:'Meta Horizon Store (VR)',
  short:'One public store with technical checks rather than taste: verify your organisation, pass the VR checks and review, then updates ship without review.',
  glance:['Verified organisation','Store review against the VRCs','Plan 2 weeks or more'],
  stages:{
    access:{ points:['Sign up on the Meta developer site, create an organisation (a team) and verify an admin or the business before publishing.','Headsets need a developer team and a verified account to enter developer mode.'],
      facts:[{ claim:'An organisation must verify an admin’s identity or the business before it can publish or update apps; admin verification with a government ID usually takes minutes.', asOf:CHECKED, src:'https://developers.meta.com/horizon/resources/publish-organization-verification/' }] },
    build:{ points:['OpenXR is the recommended path in Unity, Unreal and Godot; Godot adds Meta features through the official OpenXR Vendors plugin.','Every uploaded build, test channels included, must meet the release packaging rules.'],
      facts:[{ claim:'Apps created after 1 March 2026 must target Android 14 (API 34).', asOf:CHECKED, src:'https://developers.meta.com/horizon/blog/meta-quest-apps-android-14-march-1/' },
        { claim:'Immersive apps must keep rendering at 60 fps or more at an allowed refresh rate.', asOf:CHECKED, src:'https://developers.meta.com/horizon/resources/vrc-quest-performance-1/' },
        { claim:'Immersive apps must run 45 minutes without crashing or freezing.', asOf:CHECKED, src:'https://developers.meta.com/horizon/resources/vrc-quest-functional-1/' }] },
    cert:{ points:['Only the production channel is reviewed; alpha, beta and release-candidate channels let testers in without review.','Review checks technical, content and privacy requirements (the VRCs), not subjective quality.'],
      facts:[{ claim:'Meta asks developers to submit for review at least two weeks ahead of launch.', asOf:CHECKED, src:'https://developers.meta.com/horizon/resources/publish-submit/' }] },
    ratings:{ points:['Every app completes the IARC questionnaire and self-certifies its age group; apps for younger users carry extra requirements.'],
      facts:[{ claim:'Age-group self-certification is required for every app on each submission or update: teens and adults, mixed ages, or children.', asOf:CHECKED, src:'https://developers.meta.com/horizon/resources/age-groups/' }] },
    store:{ points:['Store art covers hero, covers, icon, five screenshots of real content and a trailer.','A Coming Soon page can go up well before launch and collects wishlists; pre-orders are supported.'],
      facts:[{ claim:'Meta keeps 30% of net revenue; for subscriptions its share drops to 15% from the fourth month.', asOf:CHECKED, src:'https://developers.meta.com/horizon/policy/developer-distribution-agreement/' }] },
    release:{ points:['A newly published app can carry the Early Access label; switching it off cannot be undone.','After launch, a new build in the production channel ships without review; store page changes are reviewed.'],
      facts:[{ claim:'After launch, builds uploaded to production update immediately without review, and metadata changes usually take 1 to 2 business days.', asOf:CHECKED, src:'https://developers.meta.com/horizon/resources/publish-after-sub/' },
        { claim:'From 5 August 2024 Meta moved App Lab content onto the Meta Horizon Store under one set of VRCs, and apps could opt into an Early Access badge.', asOf:'2026-09-28', src:'https://developers.meta.com/horizon/blog/get-apps-ready-app-lab-meta-horizon-store-meta-quest-developers/' },
        { claim:'Meta announced in April 2024 that App Lab would no longer be a separate distribution channel and that every title meeting basic technical, content and privacy requirements would be published.', asOf:'2026-09-28', src:'https://developers.meta.com/horizon/blog/a-more-open-ecosystem-for-developers/' },
        { claim:'The default release channels are Production, RC, BETA and ALPHA; a channel holds 200 users by default (up to 2,500 on request), testers join by email, alias or URL, and only Production is reviewed.', asOf:'2026-09-28', src:'https://developers.meta.com/horizon/resources/publish-release-channels/' },
        { claim:'ovr-platform-util upload-quest-build needs --app-id, --app-secret or --token, --apk, --channel and --age-group (without it the upload is left as a draft), with optional --obb, --notes, --assets-dir and --debug-symbols-dir; channel names are not case-sensitive and store means Production.', asOf:'2026-09-28', src:'https://developers.meta.com/horizon/resources/publish-reference-platform-command-line-utility/' }],
      deploy:[
        { t:'Verify the organisation', d:'In the Developer Dashboard, verify an admin’s identity or the business so the organisation can publish.' },
        { t:'Create the app', d:'Create a Meta Horizon Store app in the dashboard and copy its app ID and app secret from Development > API.' },
        { t:'Upload to ALPHA', d:'Run ovr-platform-util upload-quest-build with --app-id, --app-secret, --apk, --age-group and --channel ALPHA, plus release notes.' },
        { t:'Invite testers', d:'On Release Channels, add testers to ALPHA, BETA or RC by email, alias or a shareable URL.', shot:{ img:'assets/platforms/quest-release-channels.webp', alt:'The Meta Developer Dashboard Release Channels page listing a Business channel and Store channels Production (Store), RC, BETA and ALPHA with build versions and user counts, and a Create Release Channel button', caption:'Release channels in the Meta Developer Dashboard: test channels take builds without review; only Production is reviewed.', credit:{ author:'Meta', url:'https://developers.meta.com/horizon/resources/publish-release-channels/', licence:'press', source:'Meta Horizon OS Developers' }, callouts:[{ x:0.5, y:0.585, t:'Only this channel is reviewed' },{ x:0.7, y:0.04, t:'Add a custom test channel' }] } },
        { t:'Check the VRCs', d:'Move the build to RC with ovr-platform-util set-release-channel-build, then test it against the Virtual Reality Checks: performance, 45 minutes without crashing, and packaging rules.' },
        { t:'Submit for review', d:'Fill in the store listing, IARC questionnaire and age group, then submit the Production build at least two weeks before launch.' },
        { t:'Ship updates', d:'After launch, upload new builds with --channel store; they go live without review while listing changes are reviewed.' }
      ],
      iv:[
        { q:'Walk me through shipping a patch on Meta Quest.', a:'Build the APK, upload it with ovr-platform-util to the RC channel, have testers check it against the VRCs, then upload or promote it to Production; after launch production builds go live without review.', follow:'How do you roll back if the patch crashes?', red:'Assuming every update waits days for review.' },
        { q:'What happened to App Lab?', a:'In August 2024 Meta folded App Lab into the Meta Horizon Store, so apps are judged on technical, content and privacy checks rather than taste, and developers can mark an app Early Access.', follow:'What does Early Access change for players?', red:'Describing App Lab as a separate store still.' },
        { q:'What are VRCs and which ones catch teams out?', a:'The Virtual Reality Checks Meta reviews against: performance at 60 fps or more at an allowed refresh rate, running 45 minutes without crashing, packaging such as the Android target level, and content and privacy rules.', follow:'How would you test the 45-minute check efficiently?', red:'Thinking the review grades fun or quality.' },
        { q:'How would you automate Quest uploads from CI?', a:'Store the app ID and app secret as CI secrets and call ovr-platform-util upload-quest-build with the APK, age group, channel and notes, uploading to a test channel and promoting by hand.', follow:'Why not upload straight to store from CI?', red:'Committing the app secret to the repo.' },
        { q:'How many testers can a test channel hold?', a:'200 by default, and up to 2,500 on request; testers join by email, alias or URL, or the channel can be made public.', follow:'When would you use a public channel?', red:'Sideloading APKs to testers instead of using channels.' }
      ] }
  },
  topics:['platform-choice']
});

PLATFORM('itch', { t:'itch.io', kind:'open', sub:'Downloads and browser games',
  short:'Anyone can upload, sell or give away a game, including browser builds, and choose how much itch.io keeps.',
  glance:['Anyone','None for free pages','None'],
  stages:{
    access:{ points:['Any account can create game pages; there are no tiers or approval to upload.'] },
    build:{ shots:[{ img:'assets/platforms/itch-edit-game-uploads.webp', alt:'The itch.io Edit game page, Uploads section: a file wine-osx-universal.zip of 118 MB tagged for macOS, with an osx-universal channel badge from butler, options to set a different price or hide the file, and buttons to upload files, choose from Dropbox or add an external file', caption:'The Edit game page’s Uploads: each file is tagged with its platforms, and a build pushed with butler shows its channel name.', credit:{ author:'itch.io (Leaf Corcoran and Amos Wenger)', url:'https://github.com/itchio/butler/blob/master/docs/images/edit-game.png', licence:'MIT', source:'butler documentation on GitHub' }, callouts:[{ x:0.57, y:0.57, t:'Channel pushed by butler' }, { x:0.08, y:0.51, t:'Platforms this file is for' }, { x:0.13, y:0.95, t:'Manual upload instead' }] }], points:['Upload downloadable builds, or a ZIP with an index.html to play in the browser.','butler, itch.io’s command-line uploader, sends only what changed between builds.','butler push takes a folder and a target user/game:channel; channel names such as windows, linux, mac or android tag the platform, and --userversion sets your own version string.','Put butler push in CI after the engine export, with the API key from butler login stored as a CI secret.','Embed options set the viewport size or click-to-launch fullscreen, an optional fullscreen button, and scrollbars.'],
      facts:[{ claim:'butler push <dir> <user>/<game>:<channel> uploads a build; channel names containing win, linux, mac or android tag the platform, --userversion or --userversion-file sets the version, and after the first push only new data is uploaded, typically saving 80 to 95%.', asOf:'2026-09-28', src:'https://raw.githubusercontent.com/itchio/butler/master/docs/pushing.md' },
        { claim:'An HTML5 ZIP must contain an index.html, and by default no more than 1,000 files, 500 MB extracted in total, 200 MB for any single file, and paths of at most 240 characters; itch.io can lift the limits on request.', asOf:'2026-09-28', src:'https://raw.githubusercontent.com/itchio/itch.io/master/docs/creators/html5.md' }] },
    cert:{ points:['Free pages publish without review. itch.io reviews new sellers before their first paid game shows in search.'] },
    ratings:{ points:['itch.io has no age-rating questionnaire; you mark adult content yourself, and since July 2025, under payment-processor pressure, adult pages can be deindexed from browse and search while itch.io reviews them, though they still work by direct link.'] },
    store:{ points:['The seller sets itch.io’s share of each sale (open revenue sharing); payouts need tax details.','Every price is a minimum: buyers can pay more, and a free game can still ask for a donation before download.','Choose a payout mode: paid directly into your own PayPal or Stripe, where you handle VAT, or collected by itch.io and paid out later, where itch.io remits VAT.'],
      facts:[{ claim:'itch.io’s open revenue sharing, launched in 2015, lets sellers set itch.io’s share, with 10% as the default.', asOf:CHECKED, src:'https://www.gamedeveloper.com/business/itch-io-launches-open-revenue-sharing' },
        { claim:'The Open Revenue Share slider in account settings sets itch.io’s cut from 0% to 100%, 10% by default.', asOf:'2026-09-28', src:'https://raw.githubusercontent.com/itchio/itch.io/master/docs/creators/payments.md' },
        { claim:'On itch.io any price is a minimum price: buyers may pay more, and free content still offers the option to pay before download.', asOf:'2026-09-28', src:'https://raw.githubusercontent.com/itchio/itch.io/master/docs/creators/pricing.md' }] },
    release:{ points:['Push updates with butler or a new upload; players with the itch.io app get them automatically.','A push is live as soon as its upload finishes, with a default patch; itch.io then builds a smaller optimised patch in the background, which can take about 30 minutes on a large game.'],
      facts:[{ claim:'After a push the default patch is available right away, and an optimised patch is regenerated on the server, which can take around 30 minutes for large games.', asOf:'2026-09-28', src:'https://raw.githubusercontent.com/itchio/butler/master/docs/pushing.md' }],
      deploy:[
        { t:'Create the project page', d:'On itch.io choose Upload new project, set the title, kind of project, pricing and visibility as a draft.' },
        { t:'Log butler in', d:'Install butler and run butler login once, or set the BUTLER_API_KEY secret on your CI runner.' },
        { t:'Push each platform channel', d:'Run butler push build/windows user/game:windows --userversion 1.2.0, and repeat for linux, mac or html5.' },
        { t:'Set the browser embed', d:'On the edit page, mark the HTML5 upload as playable in the browser, then set Embed options: viewport size or fullscreen.' },
        { t:'Check processing status', d:'Open the channel’s build list on the project page to confirm each build arrived and to follow the optimised patch as it processes.' },
        { t:'Publish the page', d:'Switch visibility from Draft to Public, save, and later pushes to the same channel patch players automatically.' }
      ],
      iv:[
        { q:'Walk me through shipping a patch on itch.io.', a:'CI exports each platform, runs butler push to the same channels with a new --userversion, checks each build arrived, and posts a devlog; players on the itch app patch automatically and only the diff is uploaded.', follow:'Why keep channel names stable between releases?', red:'Uploading a fresh ZIP each time, so players lose patching and have to redownload.' },
        { q:'Our HTML5 build will not load after upload. What do you check?', a:'That the ZIP has index.html at its root, stays under 1,000 files, 500 MB extracted and 200 MB per file, and that paths are short; then the embed options.', follow:'How would you get a 3,000-file export under the limit?', red:'Blaming the browser before checking the ZIP limits.' },
        { q:'How should we price a small game on itch.io?', a:'Set a minimum price, since every price is a minimum and players often pay more; run sales and bundles, and decide the revenue-share slider knowing 10% is the default.', follow:'What does setting the share to 0% cost you?', red:'Assuming itch.io takes a fixed 30%.' },
        { q:'Which payout mode do we choose?', a:'Direct payments reach your own PayPal or Stripe at once but make you responsible for VAT; itch.io Payouts collect for you, remit VAT and pay out later through PayPal or Payoneer.', follow:'What tax information does each mode need?', red:'Not knowing who is responsible for VAT in the chosen mode.' },
        { q:'How do you automate itch.io releases from CI?', a:'Store the butler API key as a secret, install butler in the job, push each export to its channel with the build number as --userversion, and fail the job if the push fails.', follow:'How would you publish a beta without replacing the stable build?', red:'Committing the API key or logging in interactively on the build machine.' }
      ] }
  },
  topics:['platform-choice']
});

PLATFORM('roblox', { t:'Roblox', kind:'ugc', sub:'Roblox Studio and Luau; players on phone, PC and console',
  short:'Engine, servers and economy in one: build in Roblox Studio with Luau, publish with a click, and earn Robux you can cash out, once you pass the checks that decide who can see the game.',
  stages:{
    access:{ points:['Anyone can download Roblox Studio and build privately. What is gated is reach: the wider the audience, the more identity Roblox asks of you.','Publishing publicly to players 16 and over needs an account at least two days old, an age check (a face estimate or ID) and the Maturity & Compliance Questionnaire.','Reaching all ages, including under-16s, adds government ID (or a face estimate for creators under 18), two-factor sign-in, a refundable fee or two months of a Roblox subscription, and an evaluation the game must pass.','A group (called a Community in the app) owns games the way a studio would, holds shared revenue and splits payouts. Roblox will not settle disputes inside a group, so agree ownership and splits in writing first.','Team Create adds collaborators after an age check, and pairs age groups by default: an adult can collaborate with players 16 and over only.'],
      facts:[{ claim:'Accounts are split into Roblox Kids (5 to 8), Roblox Select (9 to 15) and Roblox (16 and over); a game runs a trial for age-checked players 16 and over and qualifies for under-16s at 250 unique plays by highly engaged age-checked players within 60 days.', asOf:CHECKED, src:'https://create.roblox.com/docs/production/publishing/kids-and-select' },
        { claim:'The all-ages publishing fee is 1,000 Robux per game, refunded once the game keeps 25 highly engaged players for 60 days without moderation; expedited review costs 50,000 Robux for a 48-hour review, and either fee is forfeited if the game is permanently moderated.', asOf:CHECKED, src:'https://create.roblox.com/docs/production/publishing/publish-games-and-places' },
        { claim:'Creating a group costs 100 Robux.', asOf:CHECKED, src:'https://create.roblox.com/docs/projects/groups' }] },
    architecture:{ diagram:{ kind:'stack', title:'One Roblox game, from the player to the cloud', arrow:'trust only flows down',
        layers:[{t:'Player clients', d:'LocalScripts, UI and input; simulate parts they own'},{t:'Remotes and inputs', d:'RemoteEvents, prompts, touches: every way a client asks'},{t:'Game server', d:'Scripts own the state and check every request'},{t:'Cloud services', d:'DataStores save, MemoryStores match, MessagingService links servers'}] },
      points:['Every Roblox game is multiplayer by default and the server is the authority: it owns the game state and replicates the world, physics and chat to every client.','A change a client makes never reaches the server by itself. Clients reach the server through remotes (RemoteEvent, UnreliableRemoteEvent, RemoteFunction), through inputs the server listens to (Touched, ProximityPrompt, ClickDetector), and through physics on parts they own.','Treat every remote call as hostile: an exploiter can read client scripts, fire remotes at any rate with any arguments, and move their own character. The server checks permission, types, values (reject non-finite numbers with math.isfinite), plausibility and rate, using state it owns.','Unanchored parts near a player are simulated by that player’s client so physics feels responsive, which makes network ownership a trust boundary. Server Authority mode moves movement and physics to the server, with client prediction and rollback.','A game (a universe in the APIs) holds one or more places, which are like scenes; TeleportService moves players between places and servers.','Plan for the low end: most players are on modest phones with 100 to 300 ms of latency, and StreamingEnabled sends each client only the nearby world, so client code must expect parts to be missing.'],
      facts:[{ claim:'Server Authority mode (Workspace.AuthorityMode = Server) makes the server the single source of truth: clients send inputs, predict locally, and roll back when they mispredict.', asOf:CHECKED, src:'https://create.roblox.com/docs/projects/server-authority' },
        { claim:'A DataStore value can hold up to 4,194,304 characters per key, and each server’s default budget is 60 + 40 × players standard reads a minute, and the same for writes.', asOf:CHECKED, src:'https://create.roblox.com/docs/cloud-services/data-stores/error-codes-and-limits' },
        { claim:'MessagingService messages are at most 1 kB, and delivery is best effort, not guaranteed.', asOf:CHECKED, src:'https://create.roblox.com/docs/reference/engine/classes/MessagingService' },
        { claim:'Android is about 65% of a typical game’s players, and about 60% of those devices have 2 to 4 GB of RAM.', asOf:CHECKED, src:'https://create.roblox.com/docs/performance-optimization/test-on-hardware' }] },
    tools:{ points:['Roblox Studio is the editor, the engine and the IDE in one, and it is cloud-first: the place lives on Roblox’s servers, and publishing uploads it.','Code is Luau, a small, fast, gradually typed language derived from Lua 5.1. --!strict on a script’s first line turns on full type checking, and --!native compiles a server script to machine code.','Three script types: a Script runs on the server (or the client, set by RunContext), a LocalScript runs only on a player’s client, and a ModuleScript runs wherever it is required. Keep most code in ModuleScripts: shared ones in ReplicatedStorage, server-only ones in ServerScriptService.','Test multiplayer from day one: Studio’s Server & Clients mode runs a server with several simulated clients, with device and network simulation. Profile with the Script Profiler and the MicroProfiler, and on a real low-end phone.','Team Create edits a place live with others: the Collaborate button adds people, and those given Edit permission can join the session. Scripts are live-edited by default; Drafts mode, switched on in Experience Settings, lets each scripter edit locally and commit, with Compare With Server for conflicts.','Packages are shared, versioned copies of a model or script tree: Convert to Package, change one copy, Publish to Package, and the others update (automatically if AutoUpdate is on). Use them for anything reused across places, such as a shop or a lobby.','For git and outside editors: Script Sync mirrors scripts to local files, and the community tool Rojo builds the whole project from a file tree. A CI job can then build a place file and upload it with the Open Cloud Place Publishing API, with no Studio open.','Studio includes an AI Assistant that can edit the place, and a built-in MCP server so outside AI coding tools can read and edit scripts in the open session.'],
      facts:[{ claim:'Luau type checking has three modes, set on a script’s first line: --!nocheck, --!nonstrict (the default) and --!strict.', asOf:CHECKED, src:'https://create.roblox.com/docs/luau/type-checking' },
        { claim:'Studio’s Server & Clients test mode simulates up to 8 clients.', asOf:CHECKED, src:'https://create.roblox.com/docs/studio/testing-modes' },
        { claim:'Team Create live scripting auto-saves edits every 5 minutes; Drafts mode is off by default, and switching it needs every collaborator to leave the session.', asOf:'2026-09-28', src:'https://create.roblox.com/docs/projects/collaboration' },
        { claim:'The Open Cloud Place Publishing API is a POST to apis.roblox.com/universes/v1/{universeId}/places/{placeId}/versions?versionType=Published with an .rbxl or .rbxlx file, and needs an API key with universe-places write access to that game; it does not update EditableImage, EditableMesh, PartOperation, SurfaceAppearance or BaseWrap instances, which must be published from Studio.', asOf:'2026-09-28', src:'https://create.roblox.com/docs/cloud/guides/usage-place-publishing' },
        { claim:'Rojo is an open-source community tool, not maintained by Roblox; rojo build -o build.rbxl turns a project folder into a place file.', asOf:'2026-09-28', src:'https://rojo.space/docs/v7/getting-started/new-game/' },
        { claim:'Creator Store sellers price models and plugins in US dollars and keep 100% of net proceeds.', asOf:CHECKED, src:'https://create.roblox.com/docs/production/creator-store' }] },
    rules:{ points:['You declare your content in the Maturity & Compliance Questionnaire, and Roblox limits who can see the game to match. Answer for the most extreme content a player can meet, and retake it whenever an update changes an answer.','Every uploaded image, mesh, sound and video is moderated separately by people and automated systems, and players cannot see it until it passes.','Paid random items must show every outcome with its odds before purchase; where PolicyService reports them restricted for a player, offer a free way to earn the item, a fixed disclosed order, or direct purchase of each outcome instead.','Playable gambling is banned outright, and social hangouts and free-form creation such as drawing carry their own age gates.','The rules themselves are the Community Standards and the Terms of Use; misrepresenting content in the questionnaire is itself moderated.'],
      facts:[{ claim:'Minimal and Mild games can be seen on every account tier, Moderate games by Select and 16-and-over accounts, and Restricted games only by age-verified players 18 and over.', asOf:CHECKED, src:'https://create.roblox.com/docs/production/promotion/content-maturity' },
        { claim:'The questionnaire is under Creator Dashboard, the game, Configure, Questionnaire; a preview page shows the resulting maturity label, descriptors and regional compliance issues before Submit, and a Restricted label restarts servers to remove players who are not age-verified.', asOf:'2026-09-28', src:'https://create.roblox.com/docs/production/promotion/content-maturity' },
        { claim:'Paid random item odds must be shown as percentages summing to exactly 100% before purchase, including when the item is bought with a currency or key that was bought with Robux.', asOf:CHECKED, src:'https://create.roblox.com/docs/production/monetization/paid-random-items' }] },
    money:{ points:['Players mostly pay in Robux. Robux other players spend in your game becomes Earned Robux, which the Developer Exchange (DevEx) turns into real money.','The main products: passes (one-off perks), developer products (repeat purchases such as currency), subscriptions, paid access, private servers, and avatar items sold in the game. Rewarded video and immersive ads add ad revenue.','Grant developer products only on the server, in the receipt handler (MarketplaceService.ProcessReceipt, or the newer BindReceiptHandler), and confirm the purchase only after the grant is saved; otherwise Roblox offers the receipt again on the player’s next purchase or next join.','Never hard-code a price: regional pricing, price optimisation and subscriber discounts mean players see different prices, so read them with GetProductInfoAsync.','Creator Rewards pay for bringing engaged spenders and new players to Roblox, in place of the old engagement-based (Premium) payouts.'],
      facts:[{ claim:'Passes pay the creator 70% of the Robux spent.', asOf:CHECKED, src:'https://create.roblox.com/docs/monetize-experiences' },
        { claim:'An avatar item bought inside a game pays 30% to the item’s creator and 40% to the game’s owner.', asOf:CHECKED, src:'https://create.roblox.com/docs/marketplace/marketplace-fees-and-commissions' },
        { claim:'Roblox Plus subscribers get 10% off, rising to 20% from the third month, paid by Roblox rather than the creator; a game earns 250 Robux a month for three months for each new subscriber it signs up.', asOf:CHECKED, src:'https://create.roblox.com/docs/production/monetization/roblox-plus' },
        { claim:'Creator Rewards pay 5 Robux a day for each Active Spender (someone who spent at least $9.99 in the past 60 days) for whom the game is one of their first three of the day and who plays it at least 10 minutes.', asOf:CHECKED, src:'https://create.roblox.com/docs/creator-rewards' },
        { claim:'DevEx pays $0.0038 per Earned Robux ($114 per 30,000) for Robux earned from 2025-09-05; older balances cash out at $0.0035 and must be cashed out first. It needs age 13 or over, at least 30,000 Earned Robux, a verified email, a DevEx Portal account and a W-9 or W-8 tax form.', asOf:'2026-09-28', src:'https://create.roblox.com/docs/production/monetization/developer-exchange' },
        { claim:'From 2026-06-08, a higher DevEx rate of $0.0054 applies to Robux from developer products, passes, subscriptions and private servers bought by US players verified 18 and over, in games where no player character is ever R6.', asOf:CHECKED, src:'https://create.roblox.com/docs/production/monetization/18-plus-devex-rate' }] },
    publish:{ points:['Publishing is two steps: File → Publish to Roblox uploads the place, which starts Private; then you set its audience to Limited (playtesters, friends, community members) or Public once you meet the requirements.','Every later File → Publish to Roblox goes live for new servers at once, so test in a separate copy of the game (a second universe kept Private or Limited) and publish the same file to the live game only when it passes.','Metadata feeds discovery: keep the name stable, sum up the game in the first sentence with genre words, and never repeat keywords, which gets a game demoted.','Old servers keep running old code after an update. Restart outdated servers from the dashboard, optionally after a delay, and keep saves backward-compatible.','Ship timed content early behind a config and switch it on at release.','Read analytics in Roblox’s own order: day-one retention and session length first, then day 7 and day 30, then payer conversion, and acquisition last. Experiments runs official A/B tests on config values.'],
      facts:[{ claim:'A place file can be at most 100 MB, and at most 5 never-public games can be made public per day.', asOf:'2026-09-28', src:'https://create.roblox.com/docs/production/publishing/publish-games-and-places' },
        { claim:'A game can show up to 10 thumbnail images or videos at 16:9; videos must show real gameplay, and only 3 video uploads are allowed a month.', asOf:CHECKED, src:'https://create.roblox.com/docs/production/publishing/thumbnails' },
        { claim:'An in-game experiment runs for 14 to 60 days with a control and up to two variants.', asOf:CHECKED, src:'https://create.roblox.com/docs/production/experiments' }],
      deploy:[
        { t:'Publish the place from Studio', d:'Choose File, Publish to Roblox, fill in the name, description, creator (you or a group) and devices, then click Create.' },
        { t:'Add more places', d:'For a lobby or level in the same game, use File, Publish to Roblox As, pick the game tile, choose Add as a new place and click Create.', shot:{ img:'assets/platforms/roblox-publish-window.webp', alt:'Part of the Roblox Studio Publish to Roblox As window: Add as a new place above three places, Elemental Academy selected and labelled Current Start Place, with Roblox’s numbered markers on it and on the Overwrite button beside Cancel', caption:'Publish to Roblox As, from Roblox’s guide to changing the start place: Add as a new place heads the list, and picking a place then Overwrite replaces it.', credit:{ author:'Roblox', url:'https://create.roblox.com/docs/production/publishing/publish-games-and-places', licence:'press', source:'Roblox Creator Hub' } } },
        { t:'Pass the age check', d:'Verify your age with a face estimate or government ID in account settings, since a public game needs it.' },
        { t:'Answer the questionnaire', d:'In Creator Dashboard open the game, Configure, Questionnaire, answer for the most extreme content, check the preview label, then Submit.' },
        { t:'Set the audience', d:'Under Configure, Settings, Audience, move from Private to Limited for playtesters first, then to Public when it is ready.' },
        { t:'Test the update elsewhere', d:'Publish each update first to a separate Private or Limited test game, or upload it there from CI through the Open Cloud Place Publishing API.' },
        { t:'Publish the update live', d:'Publish the tested file to the live place, retake the questionnaire if content changed, and add release notes to your update notification.' },
        { t:'Restart outdated servers', d:'In Creator Dashboard open Configure, Server Management and restart only servers with outdated versions, with a 1 to 60 minute delay so players can finish their round, then watch the analytics dashboard for errors.' }
      ],
      iv:[
        { q:'Walk me through shipping a patch on Roblox.', a:'Build it from the Rojo project in CI, publish it to a private test game and playtest with several clients, then publish the same file to the live place, retake the questionnaire if content changed, and restart old servers with a delay while watching errors and retention.', follow:'What happens to players still on old servers?', red:'Publishing straight from Studio to the live game and never restarting old servers.' },
        { q:'How do you keep old and new servers from corrupting saves during an update?', a:'Version every DataStore record, make new code read old formats, and never write a field old code would drop, since old servers keep running until they are restarted or empty.', follow:'How would you migrate a save format that must change?', red:'Assuming every server updates the moment you publish.' },
        { q:'How would you set up version control for a Roblox team?', a:'Rojo or Script Sync puts code in git with pull requests and CI; Team Create with Drafts covers the art and build side; packages share systems across places; the Open Cloud Place Publishing API lets CI publish.', follow:'What cannot be published through the API?', red:'Saying Roblox cannot use git because places live in the cloud.' },
        { q:'An update adds blood effects. What do you have to do before publishing?', a:'Retake the Maturity & Compliance Questionnaire, because the label decides which age groups can see the game; a higher label can cut out under-16s, and a Restricted one restarts servers to drop players who are not verified.', follow:'How would you keep the game open to younger players?', red:'Treating the questionnaire as one-off paperwork done at launch.' },
        { q:'How does a Roblox studio actually get paid?', a:'Players spend Robux on passes, developer products and subscriptions; the share that becomes Earned Robux is cashed out through DevEx at a dated per-Robux rate once over 30,000, with a tax form, and a group splits payouts to members.', follow:'Why grant developer products only after the save succeeds?', red:'Quoting Robux prices as if they were dollars.' }
      ] },
    marketing:{ points:['Home recommendations work in two stages: retrieval picks candidates on engagement, retention and monetisation, then ranking orders them for each player.','Signals are averaged per player, not totalled, so a small game with deeply engaged players is not at a disadvantage.','After an update, discovery tests the game on new groups of players and widens distribution if they engage, so a first minute that loses players costs more than a small audience does.','Exposure is cut for giveaway-bait titles, metadata that does not match the game, and games that copy an existing one.','Paid reach comes from Ads Manager, with sponsored placements and search ads paid by card or with Robux converted to ad credits. Events, update notifications and social links bring existing players back.'],
      facts:[{ claim:'Roblox names play-through rate, first-play bounce rate, play days per player and playtime per player (capped at 60 minutes a day) as its most important ranking signals.', asOf:CHECKED, src:'https://create.roblox.com/docs/discovery' },
        { claim:'Ads Manager campaigns aim at Plays, Earnings or Engagement, and Robux converted to ad credits cannot be converted back.', asOf:CHECKED, src:'https://create.roblox.com/docs/production/promotion/ads-manager' },
        { claim:'A game’s social media links are shown only to age-verified players 16 and over, and only such creators can add them.', asOf:CHECKED, src:'https://create.roblox.com/docs/production/promotion/social-media-links' }] }
  },
  flow:{ kind:'flow', title:'Roblox, from Studio to every age group',
    steps:[{id:'build', t:'Build in Studio', d:'private while you work'},{id:'upload', t:'Publish to Roblox', d:'uploads; still Private'},{id:'checks', t:'Age check', d:'and the questionnaire'},{id:'public', t:'Public, 16 and over', d:'set the audience'},{id:'discover', t:'Discovery tests it', d:'per-player engagement'},{id:'trial', t:'All-ages evaluation', d:'ID, 2FA, fee or Plus'},{id:'all', t:'Kids and Select', d:'under-16s can see it'}],
    edges:[['build','upload'],['upload','checks'],['checks','public'],['public','discover'],['public','trial'],['trial','all']] },
  topics:['ugc-platforms','server-authority','server-anticheat','launch-and-discoverability','business-model']
});

PLATFORM('fortnite', { t:'Fortnite (UEFN)', kind:'ugc', sub:'Unreal Editor for Fortnite, Verse and Fortnite Creative',
  short:'Build islands inside Fortnite with Unreal Editor for Fortnite and Verse. Epic hosts everything, reviews every release, and pays from a pool shared out by engagement.',
  stages:{
    access:{ points:['An Epic account is free, and anyone can build, in Fortnite Creative on any Fortnite platform or in UEFN on a Windows PC.','Publishing and payouts need the Fortnite Developer Program, which is for adults only and gives you a creator code.','Teams are set up in the Creator Portal, and team projects publish under the team owner’s creator code.'],
      facts:[{ claim:'The Fortnite Developer Program needs age 18 or over, a real-money purchase through Epic Payments or at least $20 spent in Fortnite in the last 365 days, and a creator code of 3 to 16 characters; payouts also need a tax interview and a Hyperwallet account.', asOf:CHECKED, src:'https://dev.epicgames.com/documentation/fortnite/fortnite-developer-program' },
        { claim:'Nobody can collaborate on a UEFN project with anyone under 18.', asOf:CHECKED, src:'https://dev.epicgames.com/documentation/en-us/fortnite/collaborating-in-unreal-editor-for-fortnite' }] },
    architecture:{ points:['You build inside Fortnite’s runtime: Epic hosts the servers, networking, characters, weapons and the base game, so you work at a higher level than on Roblox.','Gameplay is built from devices, the core building blocks, which talk to each other through events and functions you bind together.','Verse covers what devices cannot: many devices can be controlled from Verse, and you can write your own Verse devices.','Scene Graph is the newer structure of entities, components and prefabs that ties the world together, and it is native to Verse.'],
      facts:[{ claim:'Scene Graph is still labelled Beta, and Epic advises caution when shipping with it.', asOf:CHECKED, src:'https://dev.epicgames.com/documentation/en-us/fortnite/scene-graph-in-unreal-editor-for-fortnite' }] },
    tools:{ points:['Fortnite Creative is the in-game sandbox on every Fortnite platform. UEFN is an Unreal-based editor for PC that adds landscape sculpting, lighting and Verse.','Verse is Epic’s language for games. A function can fail only if it has the <decides> effect. Failable expressions, such as array indexing, comparisons and calls to such functions (written with square brackets), run only in a failure context such as if, which rolls back their effects when they fail. Concurrency is part of the language.','Live edit sessions sync changes between UEFN and a running Creative game, so you test inside Fortnite itself.','Version control is built in: UEFN’s revision control, formerly Unreal Revision Control, now runs on Lore, an open-source version control tool Epic maintains. The bottom toolbar shows Revision Control, Sync Changes or At Latest, and Check-in Changes; checking an asset out marks it for teammates in the Outliner, and History and Revert work per asset.','Auto Checkout locks an asset as soon as you change it, and Auto Revert undoes your edits to an asset a teammate already has checked out, so sync before each session and check in small changes with a changelist description. Lore does not track the history of source files from other tools, such as Blender or Photoshop files, so keep those elsewhere. For a Verse-heavy team, arguably, small devices in separate files mean two people rarely need the same one.'],
      facts:[{ claim:'UEFN runs on PC only, while Fortnite Creative runs on Switch, Xbox, PlayStation, Android, iOS and PC.', asOf:CHECKED, src:'https://dev.epicgames.com/documentation/en-us/fortnite/install-and-launch-fortnite-creative-and-unreal-editor-for-fortnite' },
        { claim:'Epic’s Lore Version Control page (its old Unreal Revision Control address now redirects there) calls Lore an open-source version control tool maintained by Epic that powers UEFN’s in-editor version control, saving the island and its assets as incremental revisions; the Check-in Changes window asks for a changelist description.', asOf:'2026-09-28', src:'https://dev.epicgames.com/documentation/fortnite/lore-version-control-in-unreal-editor-for-fortnite' }] },
    rules:{ points:['Islands must follow the Fortnite Developer Rules and Epic’s content guidelines. Moderation reviews the metadata and assets first, then the island itself, and a rejection can be appealed.','Common rejections: misleading thumbnails, advertising your creator code inside the island, photos of real people, and profanity.','Every island needs an IARC rating from a questionnaire in the Creator Portal, and Epic pays the licence fee.'],
      facts:[{ claim:'Fortnite caps island ratings at Teen (ESRB) in North America and PEGI 12 in Europe; an island rated above a region’s cap is unavailable there, and one above the cap everywhere cannot be published.', asOf:CHECKED, src:'https://dev.epicgames.com/documentation/en-us/fortnite/iarc-overview-and-faqs-in-fortnite-creative' }] },
    money:{ points:['Engagement payouts share out a pool funded by Fortnite’s Item Shop, by how much paying players engage with your island, with extra weight for bringing in new and returning players.','In-island transactions sell items for V-Bucks, defined as Verse entitlements. Paid random items must show their odds, and items that give an advantage must be declared.'],
      facts:[{ claim:'The Engagement Pool receives 40% of eligible net revenue from the Item Shop and related real-money purchases, plus 50% of Sponsored Row revenue (100% from that feature’s launch through the end of 2026); engagement is measured per calendar month and paid 30 days after the month ends.', asOf:'2026-09-28', src:'https://dev.epicgames.com/documentation/en-us/fortnite/engagement-payout-in-fortnite-creative' },
        { claim:'Creators receive 50% of the V-Bucks value of in-island sales, raised to 100% from 2026-01-09 through 2027-01-31; V-Bucks value is real-money spend minus platform fees.', asOf:CHECKED, src:'https://dev.epicgames.com/documentation/en-us/fortnite/in-island-transactions-overview-in-fortnite' },
        { claim:'In-island items cost 50 to 5,000 V-Bucks in steps of 50, work only in the island where they were bought, and cannot be gifted to another player.', asOf:CHECKED, src:'https://dev.epicgames.com/documentation/en-us/fortnite/in-island-transactions-overview-in-fortnite' }] },
    publish:{ points:['Publishing from Creative or UEFN creates a private version. Then create a release in the Creator Portal with game details, the IARC questionnaire, media and visibility, and submit it for review.','An island code has one published release at a time; each update is a new private version turned into a new release, reviewed again, with notes on what changed since the last one.','Releases can be scheduled 1 to 90 days ahead, or held unpublished after approval and published later. An unpublished island keeps its code and can be republished.','Creator Portal analytics show impressions, clicks, playtime and players, filterable by country, platform, party size and source.'],
      facts:[{ claim:'Every island is enrolled in automatic A/B thumbnail testing, which creators can opt out of.', asOf:CHECKED, src:'https://dev.epicgames.com/documentation/fortnite/publishing-islands-in-fortnite-creative' },
        { claim:'A release moves through six Creator Portal screens: Game Details (including what changed from the previous release), Rating (an IARC contact email and questionnaire), In-Island Transactions, Promotional Media, Attribution for third-party assets, and Visibility (publish automatically, on a scheduled date and time, or manually later, as Listed or Unlisted); a red exclamation mark flags any screen missing information.', asOf:'2026-09-28', src:'https://dev.epicgames.com/documentation/fortnite/publishing-from-the-creator-portal-in-fortnite-creative' }],
      deploy:[
        { t:'Publish a private version', d:'In UEFN open the Project menu on the toolbar and choose Publish Project, which uploads a new private version.' },
        { t:'Open the island in the portal', d:'In the Creator Portal choose Projects, open the island, go to its Publishing page and the Private Versions tab.' },
        { t:'Create the release', d:'Pick the private version and click Create release; fix any errors the validation popup reports (a version with experimental features cannot be released), then click Continue.', shot:{ img:'assets/platforms/fortnite-create-release.webp', alt:'The Creator Portal Publishing page with Releases and Private Versions tabs, a highlighted Create release button, and empty Published and Unpublished lists', caption:'The Publishing page in the Creator Portal: one published release per island code, and past or in-review releases under Unpublished.', credit:{ author:'Epic Games', url:'https://dev.epicgames.com/documentation/en-us/fortnite/publishing-islands-in-fortnite-creative', licence:'press', source:'Epic Developer Community' }, callouts:[{ x:0.86, y:0.59, t:'Published: the one live release for this island code' }] } },
        { t:'Fill in game details', d:'On Game Details write the public title, description and tags, and note what changed from the previous release.' },
        { t:'Answer the IARC questionnaire', d:'On the Rating tab give a contact email for IARC and answer its questionnaire, which returns regional ratings.' },
        { t:'Add media and attribution', d:'Review any items for sale on In-Island Transactions, upload thumbnails, trailer and lobby background on Promotional Media, then credit any third-party assets on Attribution.' },
        { t:'Choose visibility and submit', d:'On Visibility choose to publish automatically, on a scheduled date and time, or manually later, and Listed or Unlisted; clear every red exclamation mark, then click Submit for review.' },
        { t:'Publish and watch analytics', d:'After approval publish at once or on schedule, then watch playtime, retention and bounce in the portal analytics.' }
      ],
      iv:[
        { q:'Walk me through shipping a patch to a live Fortnite island.', a:'Sync and check in through revision control, run a live edit session to test, Publish Project for a new private version, create a release from it with change notes and an updated IARC answer if content changed, submit, and publish after approval or schedule it for a quiet hour.', follow:'What do players see while the new release is in review?', red:'Thinking Publish Project in UEFN makes the change live.' },
        { q:'Your update was rejected by moderation. What do you do?', a:'Read the reason, fix it, usually metadata such as a misleading thumbnail or a creator code shown in the island, submit a new release, and appeal only if the rejection is wrong; the old release stays live meanwhile.', follow:'How would you avoid the same rejection next time?', red:'Resubmitting the same release unchanged.' },
        { q:'How does an island earn money, and what drives the number?', a:'Engagement payouts share a pool funded by 40% of eligible Item Shop net revenue by paying players’ engagement, weighted for new and returning players, plus in-island V-Bucks sales at a dated share.', follow:'Which metric would you try to move first?', red:'Believing payouts are a fixed amount per play.' },
        { q:'Two designers need to edit the same device setup. How do you avoid losing work?', a:'Revision control locks what someone checks out, so split logic into small Verse devices and separate files, sync before starting, check in small changes with descriptions, and use History and Revert when something breaks.', follow:'What would you do if a teammate left an asset checked out?', red:'Sharing a project folder over a drive instead of using revision control.' },
        { q:'How do ratings limit what you can put in an island?', a:'Every release answers the IARC questionnaire, and Fortnite caps islands at ESRB Teen and PEGI 12; above a region’s cap the island is hidden there, and above the cap everywhere it cannot publish.', follow:'How would you handle blood effects in a horror island?', red:'Assuming a mature rating just adds an age gate.' }
      ] },
    marketing:{ points:['Engagement drives distribution: several core signals (average playtime, retention, qualified play-through rate) are per player, so deep engagement can outperform a large audience.','New islands are tested in Discover and scored automatically on engagement, retention, social and similarity signals, plus a human check.','Islands whose metadata copies another island are shown less; reusing Verse code and devices does not count as copying.','Paid placement is the Sponsored Row, an auction you bid on from the Creator Portal.'],
      facts:[{ claim:'New islands are tested in Discover for up to two weeks.', asOf:CHECKED, src:'https://dev.epicgames.com/documentation/fortnite/how-discover-works-in-fortnite' },
        { claim:'Discover measures average playtime (capped at 120 minutes a session), concurrent players, bounce rate, retention, social play, qualified play-through rate and 7-day unique players.', asOf:CHECKED, src:'https://dev.epicgames.com/documentation/fortnite/how-discover-works-in-fortnite' }] }
  },
  flow:{ kind:'flow', title:'Fortnite, from UEFN to Discover',
    steps:[{id:'build', t:'Build the island', d:'UEFN on PC, or Creative'},{id:'program', t:'Developer Program', d:'18 and over, creator code'},{id:'private', t:'Publish Project', d:'a private version'},{id:'release', t:'Create a release', d:'details, IARC, media'},{id:'review', t:'Moderation', d:'metadata, then the island'},{id:'live', t:'Live in Discover', d:'tested for up to two weeks'}],
    edges:[['build','program'],['program','private'],['private','release'],['release','review'],['review','live']] },
  topics:['ugc-platforms','platform-choice','launch-and-discoverability','business-model']
});

// The comparison table on the Platforms page: one row per store or console,
// from each guide's `glance` (access, review gate, typical turnaround).
function platformMatrix(){
  const main = PLATFORMS.filter(p => p.kind !== 'open' && p.kind !== 'ugc');
  return { kind: 'matrix', title: 'The platforms at a glance', rows: main.map(p => p.t), cols: ['Access', 'Review gate', 'Turnaround'], cells: main.map(p => p.glance),
    note: 'Console turnaround and terms are under NDA. Check each guide’s dated facts before you plan around a number.' };
}
